[
  
  {id:1,  zh:"你好",    pinyin:"nǐ hǎo",      pos:"fixed",    meaning:"مرحباً / أهلاً",                    exZh:"你好，王老师！",          exPinyin:"Nǐ hǎo, Wáng lǎoshī!",          exEn:"Hello, Teacher Wang!", s2:{zh:"你好，请问你叫什么名字？",py:"Nǐ hǎo, qǐngwèn nǐ jiào shénme míngzi?",ar:"مرحباً، ما اسمك من فضلك؟"}, s3:{zh:"你好！很高兴认识你。",py:"Nǐ hǎo! Hěn gāoxìng rènshi nǐ.",ar:"مرحباً! سعيد بمعرفتك."}},

  {id:2,  zh:"王老师",  pinyin:"Wáng lǎoshī", pos:"noun",     meaning:"الأستاذة/الأستاذ وانغ",             exZh:"王老师是中国人。",         exPinyin:"Wáng lǎoshī shì Zhōngguó rén.",  exEn:"Teacher Wang is Chinese.", s2:{zh:"王老师，您好！",py:"Wáng lǎoshī, nín hǎo!",ar:"مرحباً أستاذة وانغ!"}, s3:{zh:"王老师教中文。",py:"Wáng lǎoshī jiāo Zhōngwén.",ar:"الأستاذة وانغ تدرّس الصينية."}},

  {id:3,  zh:"大家",    pinyin:"dàjiā",       pos:"pronoun",  meaning:"الجميع / كلكم",                     exZh:"大家好！",                exPinyin:"Dàjiā hǎo!",                     exEn:"Hello everyone!", s2:{zh:"大家一起学习！",py:"Dàjiā yīqǐ xuéxí!",ar:"الجميع يتعلم معاً!"}, s3:{zh:"大家都是学生。",py:"Dàjiā dōu shì xuéshēng.",ar:"الجميع طلاب."}},

  {id:4,  zh:"好",      pinyin:"hǎo",         pos:"adjective",meaning:"جيد / بخير",                       exZh:"我很好。",                exPinyin:"Wǒ hěn hǎo.",                    exEn:"I'm very good.", s2:{zh:"今天天气很好。",py:"Jīntiān tiānqì hěn hǎo.",ar:"الطقس اليوم جيد."}, s3:{zh:"你好吗？我很好，谢谢。",py:"Nǐ hǎo ma? Wǒ hěn hǎo, xièxie.",ar:"كيف حالك؟ أنا بخير، شكراً."}},

  {id:5,  zh:"学生",    pinyin:"xuésheng",    pos:"noun",     meaning:"طالب",                             exZh:"我是学生。",              exPinyin:"Wǒ shì xuésheng.",               exEn:"I am a student.", s2:{zh:"她是一个好学生。",py:"Tā shì yī gè hǎo xuéshēng.",ar:"هي طالبة جيدة."}, s3:{zh:"学生们在教室里。",py:"Xuéshēngmen zài jiàoshì lǐ.",ar:"الطلاب في الفصل."}},

  {id:6,  zh:"们",      pinyin:"men",         pos:"particle", meaning:"(لاحقة الجمع)",                    exZh:"同学们好！",              exPinyin:"Tóngxuémen hǎo!",                exEn:"Hello classmates!", s2:{zh:"同学们好！",py:"Tóngxuémen hǎo!",ar:"مرحباً أيها الطلاب!"}, s3:{zh:"他们是我的同学们。",py:"Tāmen shì wǒ de tóngxuémen.",ar:"هم زملائي في الفصل."}},

  {id:7,  zh:"老师",    pinyin:"lǎoshī",      pos:"noun",     meaning:"معلم / أستاذ",                     exZh:"她是我的老师。",           exPinyin:"Tā shì wǒ de lǎoshī.",           exEn:"She is my teacher.", s2:{zh:"我的老师很好。",py:"Wǒ de lǎoshī hěn hǎo.",ar:"معلمي جيد جداً."}, s3:{zh:"老师在教室里上课。",py:"Lǎoshī zài jiàoshì lǐ shàngkè.",ar:"المعلم يدرّس في الفصل."}},

  {id:8,  zh:"您",      pinyin:"nín",         pos:"pronoun",  meaning:"حضرتك (صيغة احترام)",              exZh:"老师，您好！",             exPinyin:"Lǎoshī, nín hǎo!",               exEn:"Hello, teacher! (polite)", s2:{zh:"您好，王先生！",py:"Nín hǎo, Wáng xiānsheng!",ar:"مرحباً بك السيد وانغ!"}, s3:{zh:"老师，您喝茶吗？",py:"Lǎoshī, nín hē chá ma?",ar:"أستاذ، هل تشرب الشاي؟"}},

  {id:9,  zh:"你们",    pinyin:"nǐmen",       pos:"pronoun",  meaning:"أنتم",                             exZh:"你们是中国人吗？",         exPinyin:"Nǐmen shì Zhōngguó rén ma?",     exEn:"Are you (all) Chinese?", s2:{zh:"你们都是中国人吗？",py:"Nǐmen dōu shì Zhōngguó rén ma?",ar:"هل كلكم صينيون؟"}, s3:{zh:"你们学什么？",py:"Nǐmen xué shénme?",ar:"ماذا تدرسون؟"}},

  {id:10, zh:"谢谢",    pinyin:"xièxie",      pos:"verb",     meaning:"شكراً",                            exZh:"谢谢你。",                exPinyin:"Xièxie nǐ.",                     exEn:"Thank you.", s2:{zh:"非常感谢你的帮助。",py:"Fēicháng gǎnxiè nǐ de bāngzhù.",ar:"شكراً جزيلاً على مساعدتك."}, s3:{zh:"谢谢你来我家。",py:"Xièxie nǐ lái wǒ jiā.",ar:"شكراً على زيارتك لمنزلي."}},

  {id:11, zh:"不客气",  pinyin:"bú kèqi",     pos:"fixed",    meaning:"العفو / على الرحب",               exZh:"谢谢！——不客气。",         exPinyin:"Xièxie! —— Bú kèqi.",            exEn:"Thanks! — You're welcome.", s2:{zh:"不客气，这是我的工作。",py:"Bú kèqi, zhè shì wǒ de gōngzuò.",ar:"على الرحب، هذا عملي."}, s3:{zh:"谢谢！——没什么，不客气。",py:"Xièxie! —— Méi shénme, bú kèqi.",ar:"شكراً! —— بلا داعي، العفو."}},

  {id:12, zh:"同学",    pinyin:"tóngxué",     pos:"noun",     meaning:"زميل الفصل",                      exZh:"他是我的同学。",           exPinyin:"Tā shì wǒ de tóngxué.",          exEn:"He is my classmate.", s2:{zh:"他是我的好同学。",py:"Tā shì wǒ de hǎo tóngxué.",ar:"هو زميلي الجيد في الفصل."}, s3:{zh:"我有很多同学。",py:"Wǒ yǒu hěn duō tóngxué.",ar:"لدي كثير من زملاء الفصل."}},

  {id:13, zh:"再见",    pinyin:"zàijiàn",     pos:"verb",     meaning:"وداعاً / مع السلامة",             exZh:"老师，再见！",             exPinyin:"Lǎoshī, zàijiàn!",               exEn:"Goodbye, teacher!", s2:{zh:"老师，明天见！",py:"Lǎoshī, míngtiān jiàn!",ar:"إلى اللقاء يا أستاذ، أراك غداً!"}, s3:{zh:"再见，明天上课。",py:"Zàijiàn, míngtiān shàngkè.",ar:"وداعاً، غداً لدينا درس."}},

  {id:14, zh:"请问",    pinyin:"qǐngwèn",     pos:"verb",     meaning:"هل يمكنني أن أسأل؟ / عفواً",     exZh:"请问，你叫什么名字？",     exPinyin:"Qǐngwèn, nǐ jiào shénme míngzi?",exEn:"Excuse me, what's your name?", s2:{zh:"请问，图书馆在哪儿？",py:"Qǐngwèn, túshūguǎn zài nǎr?",ar:"عفواً، أين المكتبة؟"}, s3:{zh:"请问，你是老师吗？",py:"Qǐngwèn, nǐ shì lǎoshī ma?",ar:"هل أنت المعلم من فضلك؟"}},

  {id:15, zh:"你",      pinyin:"nǐ",          pos:"pronoun",  meaning:"أنت",                             exZh:"你很高兴。",              exPinyin:"Nǐ hěn gāoxìng.",                exEn:"You are very happy.", s2:{zh:"你是哪国人？",py:"Nǐ shì nǎ guó rén?",ar:"من أي بلد أنت؟"}, s3:{zh:"你今天忙吗？",py:"Nǐ jīntiān máng ma?",ar:"هل أنت مشغول اليوم؟"}},

  {id:16, zh:"叫",      pinyin:"jiào",        pos:"verb",     meaning:"اسمه / يُسمّى",                    exZh:"我叫大卫。",              exPinyin:"Wǒ jiào Dàwèi.",                 exEn:"My name is David.", s2:{zh:"你叫什么名字？",py:"Nǐ jiào shénme míngzi?",ar:"ما اسمك؟"}, s3:{zh:"她叫王芳。",py:"Tā jiào Wáng Fāng.",ar:"اسمها وانغ فانغ."}},

  {id:17, zh:"什么",    pinyin:"shénme",      pos:"pronoun",  meaning:"ماذا؟ / ما؟",                     exZh:"这是什么？",              exPinyin:"Zhè shì shénme?",                exEn:"What is this?", s2:{zh:"这是什么东西？",py:"Zhè shì shénme dōngxi?",ar:"ما هذا الشيء؟"}, s3:{zh:"你要什么？",py:"Nǐ yào shénme?",ar:"ماذا تريد؟"}},

  {id:18, zh:"名字",    pinyin:"míngzi",      pos:"noun",     meaning:"اسم",                             exZh:"你的名字是什么？",         exPinyin:"Nǐ de míngzi shì shénme?",       exEn:"What is your name?", s2:{zh:"你的名字很好听。",py:"Nǐ de míngzi hěn hǎotīng.",ar:"اسمك جميل جداً."}, s3:{zh:"这是我的中文名字。",py:"Zhè shì wǒ de Zhōngwén míngzi.",ar:"هذا اسمي باللغة الصينية."}},

  {id:19, zh:"我",      pinyin:"wǒ",          pos:"pronoun",  meaning:"أنا",                             exZh:"我是老师。",              exPinyin:"Wǒ shì lǎoshī.",                 exEn:"I am a teacher.", s2:{zh:"我是学生，不是老师。",py:"Wǒ shì xuéshēng, bú shì lǎoshī.",ar:"أنا طالب وليس معلماً."}, s3:{zh:"我来自埃及。",py:"Wǒ lái zì Āijí.",ar:"أنا من مصر."}},

  {id:20, zh:"不",      pinyin:"bù",          pos:"adverb",   meaning:"لا / ليس",                        exZh:"我不是学生。",            exPinyin:"Wǒ bú shì xuésheng.",            exEn:"I am not a student.", s2:{zh:"我不去学校，我在家。",py:"Wǒ bú qù xuéxiào, wǒ zài jiā.",ar:"لن أذهب للمدرسة، أنا في البيت."}, s3:{zh:"他不喝茶，他喝水。",py:"Tā bù hē chá, tā hē shuǐ.",ar:"هو لا يشرب الشاي، يشرب الماء."}},

  {id:21, zh:"是",      pinyin:"shì",         pos:"verb",     meaning:"هو / يكون",                       exZh:"他是法国人。",            exPinyin:"Tā shì Fǎguó rén.",              exEn:"He is French.", s2:{zh:"她是我的老师。",py:"Tā shì wǒ de lǎoshī.",ar:"هي معلمتي."}, s3:{zh:"这是我的书。",py:"Zhè shì wǒ de shū.",ar:"هذا كتابي."}},

  {id:22, zh:"对不起",  pinyin:"duìbuqǐ",     pos:"fixed",    meaning:"آسف / معذرة",                     exZh:"对不起，我迟到了。",       exPinyin:"Duìbuqǐ, wǒ chídào le.",         exEn:"Sorry, I'm late.", s2:{zh:"对不起，我迟到了。",py:"Duìbuqǐ, wǒ chídào le.",ar:"آسف، لقد تأخرت."}, s3:{zh:"对不起，我不知道。",py:"Duìbuqǐ, wǒ bù zhīdào.",ar:"آسف، لا أعرف."}},

  {id:23, zh:"没关系",  pinyin:"méi guānxi",  pos:"fixed",    meaning:"لا بأس / لا يهم",                 exZh:"没关系，不客气。",         exPinyin:"Méi guānxi, bú kèqi.",           exEn:"Never mind, you're welcome.", s2:{zh:"没关系，下次注意。",py:"Méi guānxi, xià cì zhùyì.",ar:"لا بأس، انتبه في المرة القادمة."}, s3:{zh:"——对不起！——没关系。",py:"—— Duìbuqǐ! —— Méi guānxi.",ar:"——آسف! ——لا يهم."}},

  {id:24, zh:"没事",    pinyin:"méishì",      pos:"verb",     meaning:"لا يهم / بسيطة",                  exZh:"对不起！——没事。",         exPinyin:"Duìbuqǐ! —— Méishì.",            exEn:"Sorry! — It's okay.", s2:{zh:"没事，别担心。",py:"Méishì, bié dānxīn.",ar:"لا بأس، لا تقلق."}, s3:{zh:"没事，我可以帮你。",py:"Méishì, wǒ kěyǐ bāng nǐ.",ar:"لا مشكلة، أستطيع مساعدتك."}},

  {id:25, zh:"很",      pinyin:"hěn",         pos:"adverb",   meaning:"جداً / كثيراً",                   exZh:"他很高兴。",              exPinyin:"Tā hěn gāoxìng.",                exEn:"He is very happy.", s2:{zh:"这个菜很好吃。",py:"Zhège cài hěn hǎochī.",ar:"هذا الطبق لذيذ جداً."}, s3:{zh:"这本书很有意思。",py:"Zhè běn shū hěn yǒuyìsi.",ar:"هذا الكتاب ممتع جداً."}},

  {id:26, zh:"高兴",    pinyin:"gāoxìng",     pos:"adjective",meaning:"سعيد / مسرور",                    exZh:"认识你很高兴。",           exPinyin:"Rènshi nǐ hěn gāoxìng.",         exEn:"Nice to meet you.", s2:{zh:"认识你，我很高兴。",py:"Rènshi nǐ, wǒ hěn gāoxìng.",ar:"أنا سعيد بمعرفتك."}, s3:{zh:"他今天很高兴。",py:"Tā jīntiān hěn gāoxìng.",ar:"هو سعيد جداً اليوم."}},

  {id:27, zh:"认识",    pinyin:"rènshi",      pos:"verb",     meaning:"يعرف / يتعرف على",                exZh:"我认识他。",              exPinyin:"Wǒ rènshi tā.",                  exEn:"I know him.", s2:{zh:"我不认识他。",py:"Wǒ bú rènshi tā.",ar:"أنا لا أعرفه."}, s3:{zh:"你认识她吗？",py:"Nǐ rènshi tā ma?",ar:"هل تعرفها؟"}},

  {id:28, zh:"也",      pinyin:"yě",          pos:"adverb",   meaning:"أيضاً / كذلك",                    exZh:"我也是学生。",            exPinyin:"Wǒ yě shì xuésheng.",            exEn:"I am also a student.", s2:{zh:"我也学习中文。",py:"Wǒ yě xuéxí Zhōngwén.",ar:"أنا أيضاً أدرس الصينية."}, s3:{zh:"她也是中国人。",py:"Tā yě shì Zhōngguó rén.",ar:"هي أيضاً صينية."}},

  {id:29, zh:"人",      pinyin:"rén",         pos:"noun",     meaning:"شخص / إنسان",                     exZh:"他是一个好人。",           exPinyin:"Tā shì yí ge hǎo rén.",          exEn:"He is a good person.", s2:{zh:"他是一个好人。",py:"Tā shì yī gè hǎo rén.",ar:"هو شخص طيب."}, s3:{zh:"外面有很多人。",py:"Wàimiàn yǒu hěn duō rén.",ar:"هناك كثير من الناس في الخارج."}},

  {id:30, zh:"的",      pinyin:"de",          pos:"particle", meaning:"(أداة الملكية/الإضافة)",          exZh:"这是我的书。",             exPinyin:"Zhè shì wǒ de shū.",             exEn:"This is my book.", s2:{zh:"这是我的书包。",py:"Zhè shì wǒ de shūbāo.",ar:"هذه حقيبتي المدرسية."}, s3:{zh:"他是我们的老师。",py:"Tā shì wǒmen de lǎoshī.",ar:"هو معلمنا."}},

  {id:31, zh:"中国",    pinyin:"Zhōngguó",    pos:"noun",     meaning:"الصين",                           exZh:"我爱中国。",              exPinyin:"Wǒ ài Zhōngguó.",                exEn:"I love China.", s2:{zh:"我爱中国，中国很美。",py:"Wǒ ài Zhōngguó, Zhōngguó hěn měi.",ar:"أنا أحب الصين، الصين جميلة."}, s3:{zh:"中国有很多人。",py:"Zhōngguó yǒu hěn duō rén.",ar:"في الصين كثير من الناس."}},

  {id:32, zh:"法国",    pinyin:"Fǎguó",       pos:"noun",     meaning:"فرنسا",                           exZh:"她去法国。",              exPinyin:"Tā qù Fǎguó.",                   exEn:"She goes to France.", s2:{zh:"他去法国留学。",py:"Tā qù Fǎguó liúxué.",ar:"ذهب ليدرس في فرنسا."}, s3:{zh:"法国的东西很贵。",py:"Fǎguó de dōngxi hěn guì.",ar:"الأشياء في فرنسا غالية."}},

  {id:33, zh:"中文",    pinyin:"Zhōngwén",    pos:"noun",     meaning:"اللغة الصينية",                   exZh:"我学习中文。",            exPinyin:"Wǒ xuéxí Zhōngwén.",             exEn:"I study Chinese.", s2:{zh:"我想学好中文。",py:"Wǒ xiǎng xuéhǎo Zhōngwén.",ar:"أريد أن أتقن اللغة الصينية."}, s3:{zh:"中文很难，也很有意思。",py:"Zhōngwén hěn nán, yě hěn yǒuyìsi.",ar:"الصينية صعبة وممتعة في آن واحد."}},

  {id:34, zh:"这",      pinyin:"zhè",         pos:"pronoun",  meaning:"هذا / هذه",                       exZh:"这是我的朋友。",           exPinyin:"Zhè shì wǒ de péngyou.",         exEn:"This is my friend.", s2:{zh:"这是我的手机。",py:"Zhè shì wǒ de shǒujī.",ar:"هذا هاتفي."}, s3:{zh:"这个人是谁？",py:"Zhège rén shì shéi?",ar:"من هذا الشخص؟"}},

  {id:35, zh:"谁",      pinyin:"shéi",        pos:"pronoun",  meaning:"من؟",                             exZh:"他是谁？",                exPinyin:"Tā shì shéi?",                   exEn:"Who is he?", s2:{zh:"这个人是谁？",py:"Zhège rén shì shéi?",ar:"من هذا الشخص؟"}, s3:{zh:"谁知道答案？",py:"Shéi zhīdào dá'àn?",ar:"من يعرف الجواب؟"}},

  {id:36, zh:"女朋友",  pinyin:"nǚpéngyou",   pos:"noun",     meaning:"صديقة / حبيبة",                   exZh:"她不是我的女朋友。",       exPinyin:"Tā bú shì wǒ de nǚpéngyou.",     exEn:"She is not my girlfriend.", s2:{zh:"她不是我的女朋友，是我的同学。",py:"Tā bú shì wǒ de nǚpéngyou, shì wǒ de tóngxué.",ar:"هي ليست حبيبتي، بل زميلتي."}, s3:{zh:"他有女朋友了。",py:"Tā yǒu nǚpéngyou le.",ar:"أصبح لديه صديقة."}},

  {id:37, zh:"哪",      pinyin:"nǎ",          pos:"pronoun",  meaning:"أي؟",                             exZh:"你是哪国人？",            exPinyin:"Nǐ shì nǎ guó rén?",             exEn:"Which country are you from?", s2:{zh:"你是哪个国家的人？",py:"Nǐ shì nǎge guójiā de rén?",ar:"من أي دولة أنت؟"}, s3:{zh:"哪本书是你的？",py:"Nǎ běn shū shì nǐ de?",ar:"أي كتاب هو كتابك؟"}},

  {id:38, zh:"国",      pinyin:"guó",         pos:"noun",     meaning:"دولة / بلد",                      exZh:"中国是一个大国。",         exPinyin:"Zhōngguó shì yí ge dà guó.",     exEn:"China is a big country.", s2:{zh:"中国是大国。",py:"Zhōngguó shì dà guó.",ar:"الصين دولة كبيرة."}, s3:{zh:"你去哪个国家留学？",py:"Nǐ qù nǎge guójiā liúxué?",ar:"في أي دولة ستدرس؟"}},

  {id:39, zh:"她",      pinyin:"tā",          pos:"pronoun",  meaning:"هي",                              exZh:"她很漂亮。",              exPinyin:"Tā hěn piàoliang.",               exEn:"She is very beautiful.", s2:{zh:"她很聪明。",py:"Tā hěn cōngming.",ar:"هي ذكية جداً."}, s3:{zh:"她是我的妹妹。",py:"Tā shì wǒ de mèimei.",ar:"هي أختي الصغرى."}},

  {id:40, zh:"泰国",    pinyin:"Tàiguó",      pos:"noun",     meaning:"تايلاند",                         exZh:"他是泰国人。",            exPinyin:"Tā shì Tàiguó rén.",              exEn:"He is Thai.", s2:{zh:"泰国的食物很好吃。",py:"Tàiguó de shíwù hěn hǎochī.",ar:"طعام تايلاند لذيذ جداً."}, s3:{zh:"她从泰国来。",py:"Tā cóng Tàiguó lái.",ar:"هي قادمة من تايلاند."}},

  {id:41, zh:"喂",      pinyin:"wèi",         pos:"fixed",    meaning:"ألو (على الهاتف) / هيّا",         exZh:"喂，你在哪儿？",           exPinyin:"Wèi, nǐ zài nǎ'er?",             exEn:"Hello, where are you?", s2:{zh:"喂！你在哪儿？",py:"Wèi! Nǐ zài nǎr?",ar:"ألو! أين أنت؟"}, s3:{zh:"喂，我是王明。",py:"Wèi, wǒ shì Wáng Míng.",ar:"ألو، أنا وانغ مينغ."}},

  {id:42, zh:"姐姐",    pinyin:"jiějie",      pos:"noun",     meaning:"الأخت الكبرى",                    exZh:"我有一个姐姐。",           exPinyin:"Wǒ yǒu yí ge jiějie.",           exEn:"I have an older sister.", s2:{zh:"我的姐姐很漂亮。",py:"Wǒ de jiějie hěn piàoliang.",ar:"أختي الكبرى جميلة جداً."}, s3:{zh:"她的姐姐在北京工作。",py:"Tā de jiějie zài Běijīng gōngzuò.",ar:"أختها الكبرى تعمل في بكين."}},

  {id:43, zh:"工作",    pinyin:"gōngzuò",     pos:"noun",     meaning:"عمل / وظيفة",                     exZh:"你做什么工作？",           exPinyin:"Nǐ zuò shénme gōngzuò?",         exEn:"What is your job?", s2:{zh:"你做什么工作？",py:"Nǐ zuò shénme gōngzuò?",ar:"ما هو عملك؟"}, s3:{zh:"我找到工作了！",py:"Wǒ zhǎodào gōngzuò le!",ar:"وجدت عملاً!"}},

  {id:44, zh:"还",      pinyin:"hái",         pos:"adverb",   meaning:"لا يزال / ما زال",                exZh:"我还很忙。",              exPinyin:"Wǒ hái hěn máng.",               exEn:"I'm still very busy.", s2:{zh:"他还在睡觉。",py:"Tā hái zài shuìjiào.",ar:"هو لا يزال نائماً."}, s3:{zh:"外面还在下雨。",py:"Wàimiàn hái zài xià yǔ.",ar:"لا تزال السماء تمطر."}},

  {id:45, zh:"忙",      pinyin:"máng",        pos:"adjective",meaning:"مشغول",                           exZh:"你今天忙吗？",            exPinyin:"Nǐ jīntiān máng ma?",            exEn:"Are you busy today?", s2:{zh:"你今天忙不忙？",py:"Nǐ jīntiān máng bù máng?",ar:"هل أنت مشغول اليوم أم لا؟"}, s3:{zh:"我太忙了，没有时间。",py:"Wǒ tài máng le, méiyǒu shíjiān.",ar:"أنا مشغول جداً وليس لدي وقت."}},

  {id:46, zh:"吗",      pinyin:"ma",          pos:"particle", meaning:"(أداة الاستفهام)",               exZh:"你好吗？",                exPinyin:"Nǐ hǎo ma?",                     exEn:"How are you?", s2:{zh:"你好吗？",py:"Nǐ hǎo ma?",ar:"كيف حالك؟"}, s3:{zh:"你吃饭了吗？",py:"Nǐ chī fàn le ma?",ar:"هل أكلت؟"}},

  {id:47, zh:"对",      pinyin:"duì",         pos:"adjective",meaning:"صحيح / صواب",                    exZh:"你说的对。",              exPinyin:"Nǐ shuō de duì.",                exEn:"What you say is correct.", s2:{zh:"你说得对！",py:"Nǐ shuō de duì!",ar:"ما تقوله صحيح!"}, s3:{zh:"这道题对了。",py:"Zhè dào tí duì le.",ar:"هذا السؤال صحيح."}},

  {id:48, zh:"太",      pinyin:"tài",         pos:"adverb",   meaning:"للغاية / أكثر مما يجب",           exZh:"太好了！",                exPinyin:"Tài hǎo le!",                    exEn:"Excellent! / Great!", s2:{zh:"太好了，谢谢！",py:"Tài hǎo le, xièxie!",ar:"رائع جداً، شكراً!"}, s3:{zh:"这件衣服太贵了。",py:"Zhè jiàn yīfu tài guì le.",ar:"هذه الملابس غالية جداً."}},

  {id:49, zh:"我们",    pinyin:"wǒmen",       pos:"pronoun",  meaning:"نحن",                             exZh:"我们是朋友。",            exPinyin:"Wǒmen shì péngyou.",             exEn:"We are friends.", s2:{zh:"我们一起去吃饭吧。",py:"Wǒmen yīqǐ qù chī fàn ba.",ar:"لنذهب معاً لتناول الطعام."}, s3:{zh:"我们是一家人。",py:"Wǒmen shì yī jiā rén.",ar:"نحن عائلة واحدة."}},

  {id:50, zh:"想",      pinyin:"xiǎng",       pos:"verb",     meaning:"يريد / يفتقد / يفكر",             exZh:"我很想你。",              exPinyin:"Wǒ hěn xiǎng nǐ.",               exEn:"I miss you very much.", s2:{zh:"我很想回家。",py:"Wǒ hěn xiǎng huí jiā.",ar:"أنا أشتاق كثيراً للعودة للبيت."}, s3:{zh:"你在想什么？",py:"Nǐ zài xiǎng shénme?",ar:"بماذا تفكر؟"}},

  {id:51, zh:"有",      pinyin:"yǒu",         pos:"verb",     meaning:"لديه / يوجد",                     exZh:"我有一个中国朋友。",       exPinyin:"Wǒ yǒu yí ge Zhōngguó péngyou.", exEn:"I have a Chinese friend.", s2:{zh:"我有两个弟弟。",py:"Wǒ yǒu liǎng gè dìdi.",ar:"لدي أخوان أصغران."}, s3:{zh:"这个书店有很多书。",py:"Zhège shūdiàn yǒu hěn duō shū.",ar:"في هذه المكتبة كتب كثيرة."}},

  {id:52, zh:"多少",    pinyin:"duōshao",     pos:"pronoun",  meaning:"كم (عدد/سعر)؟",                   exZh:"这个多少钱？",            exPinyin:"Zhège duōshao qián?",            exEn:"How much does this cost?", s2:{zh:"这个多少钱？",py:"Zhège duōshao qián?",ar:"بكم هذا؟"}, s3:{zh:"这里有多少人？",py:"Zhèlǐ yǒu duōshao rén?",ar:"كم شخصاً هنا؟"}},

  {id:53, zh:"个",      pinyin:"gè",          pos:"particle", meaning:"(عداد عام)",                      exZh:"我有一个苹果。",           exPinyin:"Wǒ yǒu yí ge píngguǒ.",         exEn:"I have one apple.", s2:{zh:"给我一个苹果。",py:"Gěi wǒ yī gè píngguǒ.",ar:"أعطني تفاحة واحدة."}, s3:{zh:"他有三个孩子。",py:"Tā yǒu sān gè háizi.",ar:"لديه ثلاثة أطفال."}},

  {id:54, zh:"哥哥",    pinyin:"gēge",        pos:"noun",     meaning:"الأخ الأكبر",                     exZh:"我的哥哥很高。",           exPinyin:"Wǒ de gēge hěn gāo.",            exEn:"My older brother is tall.", s2:{zh:"我的哥哥是医生。",py:"Wǒ de gēge shì yīshēng.",ar:"أخي الأكبر طبيب."}, s3:{zh:"哥哥，你在哪儿？",py:"Gēge, nǐ zài nǎr?",ar:"أخي، أين أنت؟"}},

  {id:55, zh:"呢",      pinyin:"ne",          pos:"particle", meaning:"(أداة سؤال ناعمة) وأنت؟",         exZh:"我很好，你呢？",           exPinyin:"Wǒ hěn hǎo, nǐ ne?",            exEn:"I'm fine, and you?", s2:{zh:"我很好，你呢？",py:"Wǒ hěn hǎo, nǐ ne?",ar:"أنا بخير، وأنت؟"}, s3:{zh:"你喝茶，我呢？",py:"Nǐ hē chá, wǒ ne?",ar:"أنت تشرب الشاي، وأنا؟"}},

  {id:56, zh:"没有",    pinyin:"méiyǒu",      pos:"verb",     meaning:"لا يوجد / ليس لديه",              exZh:"我没有弟弟。",            exPinyin:"Wǒ méiyǒu dìdi.",                exEn:"I don't have a younger brother.", s2:{zh:"我没有妹妹，只有哥哥。",py:"Wǒ méiyǒu mèimei, zhǐ yǒu gēge.",ar:"ليس لدي أخت صغرى، فقط أخ أكبر."}, s3:{zh:"他没有工作。",py:"Tā méiyǒu gōngzuò.",ar:"ليس لديه عمل."}},

  {id:57, zh:"家",      pinyin:"jiā",         pos:"noun",     meaning:"بيت / منزل / عائلة",              exZh:"我爱我的家。",            exPinyin:"Wǒ ài wǒ de jiā.",               exEn:"I love my family/home.", s2:{zh:"我家有五口人。",py:"Wǒ jiā yǒu wǔ kǒu rén.",ar:"عائلتي من خمسة أشخاص."}, s3:{zh:"你家在哪里？",py:"Nǐ jiā zài nǎlǐ?",ar:"أين منزلك؟"}},

  {id:58, zh:"几",      pinyin:"jǐ",          pos:"pronoun",  meaning:"كم؟ (عدد قليل)",                  exZh:"你家有几口人？",           exPinyin:"Nǐ jiā yǒu jǐ kǒu rén?",        exEn:"How many people are in your family?", s2:{zh:"你家有几个人？",py:"Nǐ jiā yǒu jǐ gè rén?",ar:"كم عدد أفراد عائلتك؟"}, s3:{zh:"你有几本书？",py:"Nǐ yǒu jǐ běn shū?",ar:"كم كتاباً لديك؟"}},

  {id:59, zh:"口",      pinyin:"kǒu",         pos:"particle", meaning:"(عداد أفراد العائلة)",            exZh:"我家有三口人。",           exPinyin:"Wǒ jiā yǒu sān kǒu rén.",        exEn:"My family has three members.", s2:{zh:"我家有三口人。",py:"Wǒ jiā yǒu sān kǒu rén.",ar:"عائلتي تتكون من ثلاثة أشخاص."}, s3:{zh:"这一口饭很好吃。",py:"Zhè yī kǒu fàn hěn hǎochī.",ar:"هذه اللقمة لذيذة جداً."}},

  {id:60, zh:"爸爸",    pinyin:"bàba",        pos:"noun",     meaning:"أبو / والد",                      exZh:"我的爸爸是医生。",         exPinyin:"Wǒ de bàba shì yīshēng.",        exEn:"My father is a doctor.", s2:{zh:"爸爸，你好！",py:"Bàba, nǐ hǎo!",ar:"مرحباً يا أبي!"}, s3:{zh:"我的爸爸很高大。",py:"Wǒ de bàba hěn gāodà.",ar:"أبي طويل وكبير البنية."}},

  {id:61, zh:"妈妈",    pinyin:"māma",        pos:"noun",     meaning:"أمي / والدة",                     exZh:"妈妈，你好！",             exPinyin:"Māma, nǐ hǎo!",                  exEn:"Hello, mom!", s2:{zh:"妈妈做饭很好吃。",py:"Māma zuò fàn hěn hǎochī.",ar:"طبخ أمي لذيذ جداً."}, s3:{zh:"我想我的妈妈。",py:"Wǒ xiǎng wǒ de māma.",ar:"أنا أشتاق لأمي."}},

  {id:62, zh:"妹妹",    pinyin:"mèimei",      pos:"noun",     meaning:"الأخت الصغرى",                    exZh:"我的妹妹很可爱。",         exPinyin:"Wǒ de mèimei hěn kě'ài.",        exEn:"My younger sister is very cute.", s2:{zh:"我的妹妹七岁。",py:"Wǒ de mèimei qī suì.",ar:"أختي الصغرى عمرها سبع سنوات."}, s3:{zh:"妹妹，来吃饭了！",py:"Mèimei, lái chī fàn le!",ar:"أختي، تعالي لتناول الطعام!"}},

  {id:63, zh:"和",      pinyin:"hé",          pos:"particle", meaning:"و / مع",                          exZh:"爸爸和妈妈。",            exPinyin:"Bàba hé māma.",                  exEn:"Dad and mom.", s2:{zh:"我和我的朋友去看电影。",py:"Wǒ hé wǒ de péngyou qù kàn diànyǐng.",ar:"أنا وصديقي ذهبنا لمشاهدة فيلم."}, s3:{zh:"爸爸和妈妈都在家。",py:"Bàba hé māma dōu zài jiā.",ar:"أبي وأمي كلاهما في البيت."}},

  {id:64, zh:"儿子",    pinyin:"érzi",        pos:"noun",     meaning:"ابن",                             exZh:"他的儿子三岁。",           exPinyin:"Tā de érzi sān suì.",            exEn:"His son is three years old.", s2:{zh:"他的儿子很聪明。",py:"Tā de érzi hěn cōngming.",ar:"ابنه ذكي جداً."}, s3:{zh:"我没有儿子，只有女儿。",py:"Wǒ méiyǒu érzi, zhǐ yǒu nǚ'ér.",ar:"ليس لدي ابن، فقط ابنة."}},

  {id:65, zh:"孩子",    pinyin:"háizi",       pos:"noun",     meaning:"طفل / أطفال",                     exZh:"孩子们很高兴。",           exPinyin:"Háizimen hěn gāoxìng.",          exEn:"The children are very happy.", s2:{zh:"这个孩子叫什么名字？",py:"Zhège háizi jiào shénme míngzi?",ar:"ما اسم هذا الطفل؟"}, s3:{zh:"孩子们在外边玩。",py:"Háizimen zài wàibian wán.",ar:"الأطفال يلعبون في الخارج."}},

  {id:66, zh:"女儿",    pinyin:"nǚ'ér",       pos:"noun",     meaning:"ابنة",                            exZh:"这是我的女儿。",           exPinyin:"Zhè shì wǒ de nǚ'ér.",           exEn:"This is my daughter.", s2:{zh:"我的女儿很漂亮。",py:"Wǒ de nǚ'ér hěn piàoliang.",ar:"ابنتي جميلة جداً."}, s3:{zh:"这是他的女儿吗？",py:"Zhè shì tā de nǚ'ér ma?",ar:"هل هذه ابنته؟"}},

  {id:67, zh:"岁",      pinyin:"suì",         pos:"particle", meaning:"سنة (العمر)",                     exZh:"我今年二十岁。",           exPinyin:"Wǒ jīnnián èrshí suì.",          exEn:"I am twenty years old this year.", s2:{zh:"你今年多少岁？",py:"Nǐ jīnnián duōshao suì?",ar:"كم عمرك هذا العام؟"}, s3:{zh:"我弟弟才八岁。",py:"Wǒ dìdi cái bā suì.",ar:"أخي الأصغر عمره ثماني سنوات فقط."}},

  {id:68, zh:"他",      pinyin:"tā",          pos:"pronoun",  meaning:"هو",                              exZh:"他是我的同学。",           exPinyin:"Tā shì wǒ de tóngxué.",          exEn:"He is my classmate.", s2:{zh:"他是我最好的朋友。",py:"Tā shì wǒ zuì hǎo de péngyou.",ar:"هو أفضل أصدقائي."}, s3:{zh:"他在哪儿工作？",py:"Tā zài nǎr gōngzuò?",ar:"أين يعمل؟"}},

  {id:69, zh:"今年",    pinyin:"jīnnián",     pos:"noun",     meaning:"هذا العام",                       exZh:"我今年很忙。",            exPinyin:"Wǒ jīnnián hěn máng.",           exEn:"I am very busy this year.", s2:{zh:"今年我学了很多。",py:"Jīnnián wǒ xuéle hěn duō.",ar:"تعلمت كثيراً هذا العام."}, s3:{zh:"今年你多少岁？",py:"Jīnnián nǐ duōshao suì?",ar:"كم عمرك هذا العام؟"}},

  {id:70, zh:"多",      pinyin:"duō",         pos:"pronoun",  meaning:"كثير / كم (للسؤال عن الدرجة)",   exZh:"这个孩子多大了？",         exPinyin:"Zhège háizi duō dà le?",         exEn:"How old is this child?", s2:{zh:"你多大了？",py:"Nǐ duō dà le?",ar:"كم عمرك؟"}, s3:{zh:"你的书包有多重？",py:"Nǐ de shūbāo yǒu duō zhòng?",ar:"كم يزن حقيبتك المدرسية؟"}},

  {id:71, zh:"大",      pinyin:"dà",          pos:"adjective",meaning:"كبير",                            exZh:"他的家很大。",            exPinyin:"Tā de jiā hěn dà.",              exEn:"His home is very big.", s2:{zh:"这个房间很大，我很喜欢。",py:"Zhège fángjiān hěn dà, wǒ hěn xǐhuan.",ar:"هذه الغرفة كبيرة جداً، أحبها."}, s3:{zh:"他的手很大。",py:"Tā de shǒu hěn dà.",ar:"يده كبيرة جداً."}},


  
  {id:72,  zh:"爱",     pinyin:"ài",          pos:"verb",     meaning:"يحب / يُحبّ",                     exZh:"我爱你。",                exPinyin:"Wǒ ài nǐ.",                      exEn:"I love you.", s2:{zh:"我爱我的家人。",py:"Wǒ ài wǒ de jiārén.",ar:"أنا أحب عائلتي."}, s3:{zh:"我爱吃中国菜。",py:"Wǒ ài chī Zhōngguó cài.",ar:"أنا أحب أكل الطعام الصيني."}},

  {id:73,  zh:"吧",     pinyin:"ba",          pos:"particle", meaning:"(أداة اقتراح)",                   exZh:"我们走吧。",              exPinyin:"Wǒmen zǒu ba.",                  exEn:"Let's go.", s2:{zh:"好，我去。",py:"Hǎo, wǒ qù.",ar:"حسناً، سأذهب."}, s3:{zh:"这本书很好。",py:"Zhè běn shū hěn hǎo.",ar:"هذا الكتاب جيد جداً."}},

  {id:74,  zh:"八",     pinyin:"bā",          pos:"numeral",  meaning:"ثمانية",                          exZh:"我有八个学生。",           exPinyin:"Wǒ yǒu bā gè xuéshēng.",        exEn:"I have eight students.", s2:{zh:"一、二、三，开始！",py:"Yī, èr, sān, kāishǐ!",ar:"واحد، اثنان، ثلاثة، ابدأ!"}, s3:{zh:"我有八个朋友。",py:"Wǒ yǒu bā gè péngyou.",ar:"لدي ثمانية أصدقاء."}},

  {id:75,  zh:"百",     pinyin:"bǎi",         pos:"numeral",  meaning:"مئة",                             exZh:"这本书一百元。",           exPinyin:"Zhè běn shū yì bǎi yuán.",       exEn:"This book costs 100 yuan.", s2:{zh:"这本书一百元太贵了。",py:"Zhè běn shū yì bǎi yuán tài guì le.",ar:"هذا الكتاب بمئة يوان غالٍ جداً."}, s3:{zh:"一百个学生在学校。",py:"Yì bǎi gè xuéshēng zài xuéxiào.",ar:"مئة طالب في المدرسة."}},

  {id:76,  zh:"白天",   pinyin:"báitiān",     pos:"noun",     meaning:"النهار / وقت النهار",             exZh:"白天我上班。",            exPinyin:"Báitiān wǒ shàngbān.",           exEn:"I work during the daytime.", s2:{zh:"白天她工作，晚上她学习。",py:"Báitiān tā gōngzuò, wǎnshang tā xuéxí.",ar:"تعمل نهاراً وتدرس ليلاً."}, s3:{zh:"白天不要睡觉。",py:"Báitiān bú yào shuìjiào.",ar:"لا تنم في النهار."}},

  {id:77,  zh:"半",     pinyin:"bàn",         pos:"numeral",  meaning:"نصف",                             exZh:"我吃一半。",              exPinyin:"Wǒ chī yí bàn.",                 exEn:"I eat half.", s2:{zh:"我吃了一半的苹果。",py:"Wǒ chīle yī bàn de píngguǒ.",ar:"أكلت نصف التفاحة."}, s3:{zh:"半个小时后见。",py:"Bàn gè xiǎoshí hòu jiàn.",ar:"أراك بعد نصف ساعة."}},

  {id:78,  zh:"包子",   pinyin:"bāozi",       pos:"noun",     meaning:"خبز البخار (باوزي)",              exZh:"我吃包子。",              exPinyin:"Wǒ chī bāozi.",                  exEn:"I eat steamed buns.", s2:{zh:"早上我吃包子。",py:"Zǎoshang wǒ chī bāozi.",ar:"في الصباح آكل الباوزي."}, s3:{zh:"包子好吃吗？",py:"Bāozi hǎochī ma?",ar:"هل الباوزي لذيذ؟"}},

  {id:79,  zh:"杯子",   pinyin:"bēizi",       pos:"noun",     meaning:"كوب",                             exZh:"这是我的杯子。",           exPinyin:"Zhè shì wǒ de bēizi.",           exEn:"This is my cup.", s2:{zh:"这是我的杯子。",py:"Zhè shì wǒ de bēizi.",ar:"هذا كوبي."}, s3:{zh:"杯子里有水。",py:"Bēizi lǐ yǒu shuǐ.",ar:"في الكوب ماء."}},

  {id:80,  zh:"本",     pinyin:"běn",         pos:"particle", meaning:"(عداد للكتب)",                    exZh:"我有一本书。",            exPinyin:"Wǒ yǒu yì běn shū.",             exEn:"I have one book.", s2:{zh:"这本书是你的吗？",py:"Zhè běn shū shì nǐ de ma?",ar:"هل هذا الكتاب لك؟"}, s3:{zh:"我有三本中文书。",py:"Wǒ yǒu sān běn Zhōngwén shū.",ar:"لدي ثلاثة كتب صينية."}},

  {id:81,  zh:"边",     pinyin:"biān",        pos:"noun",     meaning:"جانب / بجانب",                    exZh:"他在我边上。",            exPinyin:"Tā zài wǒ biān shàng.",          exEn:"He is next to me.", s2:{zh:"他在我边上坐着。",py:"Tā zài wǒ biān shàng zuòzhe.",ar:"هو جالس بجانبي."}, s3:{zh:"学校在公司旁边。",py:"Xuéxiào zài gōngsī pángbiān.",ar:"المدرسة بجانب الشركة."}},

  {id:82,  zh:"病",     pinyin:"bìng",        pos:"noun",     meaning:"مرض / مريض",                      exZh:"他病了。",                exPinyin:"Tā bìng le.",                    exEn:"He is sick.", s2:{zh:"他生病了，不能上课。",py:"Tā shēngbìng le, bù néng shàngkè.",ar:"مرض ولا يستطيع حضور الدرس."}, s3:{zh:"你哪儿不舒服？",py:"Nǐ nǎr bú shūfu?",ar:"أين تشعر بالألم؟"}},

  {id:83,  zh:"不要",   pinyin:"bú yào",      pos:"adverb",   meaning:"لا تفعل",                         exZh:"不要说话。",              exPinyin:"Bú yào shuōhuà.",                exEn:"Don't talk.", s2:{zh:"不要在教室里吃东西。",py:"Bú yào zài jiàoshì lǐ chī dōngxi.",ar:"لا تأكل في الفصل الدراسي."}, s3:{zh:"不要迟到！",py:"Bú yào chídào!",ar:"لا تتأخر!"}},

  {id:84,  zh:"菜",     pinyin:"cài",         pos:"noun",     meaning:"طبق / خضروات",                    exZh:"这个菜很好吃。",           exPinyin:"Zhège cài hěn hǎochī.",          exEn:"This dish is very delicious.", s2:{zh:"今天的菜很好吃。",py:"Jīntiān de cài hěn hǎochī.",ar:"طبق اليوم لذيذ جداً."}, s3:{zh:"妈妈做的菜最好吃。",py:"Māma zuò de cài zuì hǎochī.",ar:"طبخ أمي هو الأكثر لذاذة."}},

  {id:85,  zh:"茶",     pinyin:"chá",         pos:"noun",     meaning:"شاي",                             exZh:"我喝茶。",                exPinyin:"Wǒ hē chá.",                     exEn:"I drink tea.", s2:{zh:"你喝茶还是咖啡？",py:"Nǐ hē chá háishi kāfēi?",ar:"هل تشرب الشاي أم القهوة؟"}, s3:{zh:"中国人喜欢喝茶。",py:"Zhōngguó rén xǐhuan hē chá.",ar:"الصينيون يحبون شرب الشاي."}},

  {id:86,  zh:"唱",     pinyin:"chàng",       pos:"verb",     meaning:"يُغنّي",                           exZh:"她唱歌。",                exPinyin:"Tā chàng gē.",                   exEn:"She sings.", s2:{zh:"她唱歌唱得很好。",py:"Tā chànggē chàng de hěn hǎo.",ar:"هي تغني بشكل جميل جداً."}, s3:{zh:"你会唱中文歌吗？",py:"Nǐ huì chàng Zhōngwén gē ma?",ar:"هل تستطيع الغناء بالصينية؟"}},

  {id:87,  zh:"超市",   pinyin:"chāoshì",     pos:"noun",     meaning:"سوبرماركت",                       exZh:"我去超市买东西。",         exPinyin:"Wǒ qù chāoshì mǎi dōngxi.",      exEn:"I go to the supermarket to buy things.", s2:{zh:"超市里有很多东西。",py:"Chāoshì lǐ yǒu hěn duō dōngxi.",ar:"في السوبرماركت أشياء كثيرة."}, s3:{zh:"我每天去超市买菜。",py:"Wǒ měitiān qù chāoshì mǎi cài.",ar:"أذهب للسوبرماركت يومياً لشراء الخضار."}},

  {id:88,  zh:"车",     pinyin:"chē",         pos:"noun",     meaning:"سيارة / مركبة",                   exZh:"这是我的车。",             exPinyin:"Zhè shì wǒ de chē.",             exEn:"This is my car.", s2:{zh:"这是谁的车？",py:"Zhè shì shéi de chē?",ar:"هذه سيارة من؟"}, s3:{zh:"我坐公共汽车上班。",py:"Wǒ zuò gōnggòng qìchē shàngbān.",ar:"أركب الحافلة للذهاب إلى العمل."}},

  {id:89,  zh:"吃",     pinyin:"chī",         pos:"verb",     meaning:"يأكل",                            exZh:"我吃饭。",                exPinyin:"Wǒ chī fàn.",                    exEn:"I eat a meal.", s2:{zh:"你早饭吃了吗？",py:"Nǐ zǎofàn chīle ma?",ar:"هل تناولت فطورك؟"}, s3:{zh:"我喜欢吃中国菜。",py:"Wǒ xǐhuan chī Zhōngguó cài.",ar:"أحب تناول الطعام الصيني."}},

  {id:90,  zh:"穿",     pinyin:"chuān",       pos:"verb",     meaning:"يرتدي",                           exZh:"他穿衣服。",              exPinyin:"Tā chuān yīfu.",                 exEn:"He wears clothes.", s2:{zh:"天冷了，多穿衣服。",py:"Tiān lěng le, duō chuān yīfu.",ar:"الجو برد، البس ملابس أكثر."}, s3:{zh:"你今天穿的衣服很好看。",py:"Nǐ jīntiān chuān de yīfu hěn hǎokàn.",ar:"ملابسك اليوم جميلة جداً."}},

  {id:91,  zh:"出租车", pinyin:"chūzūchē",    pos:"noun",     meaning:"تاكسي",                           exZh:"我坐出租车。",            exPinyin:"Wǒ zuò chūzūchē.",               exEn:"I take a taxi.", s2:{zh:"我坐出租车去机场。",py:"Wǒ zuò chūzūchē qù jīchǎng.",ar:"ركبت التاكسي للذهاب إلى المطار."}, s3:{zh:"出租车多少钱？",py:"Chūzūchē duōshao qián?",ar:"كم تكلف سيارة الأجرة؟"}},

  {id:92,  zh:"打电话", pinyin:"dǎ diànhuà",  pos:"fixed",    meaning:"يتصل (هاتف)",                     exZh:"我给妈妈打电话。",         exPinyin:"Wǒ gěi māma dǎ diànhuà.",        exEn:"I call my mom.", s2:{zh:"你给我打电话了吗？",py:"Nǐ gěi wǒ dǎ diànhuà le ma?",ar:"هل اتصلت بي؟"}, s3:{zh:"我给老师打电话。",py:"Wǒ gěi lǎoshī dǎ diànhuà.",ar:"أتصل بالمعلم."}},

  {id:93,  zh:"到",     pinyin:"dào",         pos:"verb",     meaning:"يصل إلى",                         exZh:"我到学校了。",            exPinyin:"Wǒ dào xuéxiào le.",             exEn:"I arrived at school.", s2:{zh:"我到北京了！",py:"Wǒ dào Běijīng le!",ar:"لقد وصلت إلى بكين!"}, s3:{zh:"火车几点到？",py:"Huǒchē jǐ diǎn dào?",ar:"في أي ساعة يصل القطار؟"}},

  {id:94,  zh:"大学",   pinyin:"dàxué",       pos:"noun",     meaning:"جامعة",                           exZh:"他在大学学习。",           exPinyin:"Tā zài dàxué xuéxí.",            exEn:"He studies at a university.", s2:{zh:"她在大学学习中文。",py:"Tā zài dàxué xuéxí Zhōngwén.",ar:"هي تدرس الصينية في الجامعة."}, s3:{zh:"哪个大学比较好？",py:"Nǎge dàxué bǐjiào hǎo?",ar:"أي جامعة أفضل؟"}},

  {id:95,  zh:"大学生", pinyin:"dàxuéshēng",  pos:"noun",     meaning:"طالب جامعي",                      exZh:"她是大学生。",             exPinyin:"Tā shì dàxuéshēng.",             exEn:"She is a university student.", s2:{zh:"他是大学生，不是中学生。",py:"Tā shì dàxuéshēng, bú shì zhōngxuéshēng.",ar:"هو طالب جامعي وليس طالب ثانوية."}, s3:{zh:"大学生每天很忙。",py:"Dàxuéshēng měitiān hěn máng.",ar:"الطلاب الجامعيون مشغولون كل يوم."}},

  {id:96,  zh:"第",     pinyin:"dì",          pos:"particle", meaning:"(سابقة ترتيبية)",                 exZh:"这是第一课。",            exPinyin:"Zhè shì dì yī kè.",              exEn:"This is the first lesson.", s2:{zh:"今天是第一天上课。",py:"Jīntiān shì dì yī tiān shàngkè.",ar:"اليوم هو أول يوم دراسة."}, s3:{zh:"他是第一个来的。",py:"Tā shì dì yī gè lái de.",ar:"هو أول من أتى."}},

  {id:97,  zh:"店",     pinyin:"diàn",        pos:"noun",     meaning:"محل / متجر",                      exZh:"这家店很大。",            exPinyin:"Zhè jiā diàn hěn dà.",           exEn:"This shop is big.", s2:{zh:"这家店里有什么？",py:"Zhè jiā diàn lǐ yǒu shénme?",ar:"ماذا يوجد في هذا المتجر؟"}, s3:{zh:"附近有书店吗？",py:"Fùjìn yǒu shūdiàn ma?",ar:"هل هناك مكتبة قريبة؟"}},

  {id:98,  zh:"点",     pinyin:"diǎn",        pos:"noun",     meaning:"الساعة (الوقت)",                  exZh:"现在三点。",              exPinyin:"Xiànzài sān diǎn.",              exEn:"It's three o'clock now.", s2:{zh:"现在几点了？",py:"Xiànzài jǐ diǎn le?",ar:"كم الساعة الآن؟"}, s3:{zh:"八点上课，请准时。",py:"Bā diǎn shàngkè, qǐng zhǔnshí.",ar:"الدرس في الثامنة، كن في الموعد."}},

  {id:99,  zh:"电话",   pinyin:"diànhuà",     pos:"noun",     meaning:"هاتف",                            exZh:"我的电话在这儿。",         exPinyin:"Wǒ de diànhuà zài zhèr.",        exEn:"My phone is here.", s2:{zh:"你的手机号码是多少？",py:"Nǐ de shǒujī hàomǎ shì duōshao?",ar:"ما هو رقم هاتفك؟"}, s3:{zh:"请给我你的电话。",py:"Qǐng gěi wǒ nǐ de diànhuà.",ar:"أعطني رقم هاتفك من فضلك."}},

  {id:100, zh:"电脑",   pinyin:"diànnǎo",     pos:"noun",     meaning:"حاسوب",                           exZh:"我有一台电脑。",           exPinyin:"Wǒ yǒu yì tái diànnǎo.",        exEn:"I have a computer.", s2:{zh:"我有一台新电脑。",py:"Wǒ yǒu yī tái xīn diànnǎo.",ar:"لدي حاسوب جديد."}, s3:{zh:"电脑在桌子上。",py:"Diànnǎo zài zhuōzi shàng.",ar:"الحاسوب على الطاولة."}},

  {id:101, zh:"电视",   pinyin:"diànshì",     pos:"noun",     meaning:"تلفاز",                           exZh:"我们看电视。",            exPinyin:"Wǒmen kàn diànshì.",             exEn:"We watch TV.", s2:{zh:"我看见她了。",py:"Wǒ kànjiàn tā le.",ar:"رأيتها."}, s3:{zh:"你看见我的书了吗？",py:"Nǐ kànjiàn wǒ de shū le ma?",ar:"هل رأيت كتابي؟"}},

  {id:102, zh:"电影",   pinyin:"diànyǐng",    pos:"noun",     meaning:"فيلم سينمائي",                    exZh:"我看电影。",              exPinyin:"Wǒ kàn diànyǐng.",               exEn:"I watch a movie.", s2:{zh:"今天我们有三节课。",py:"Jīntiān wǒmen yǒu sān jié kè.",ar:"اليوم لدينا ثلاث حصص."}, s3:{zh:"这节课很有意思。",py:"Zhè jié kè hěn yǒuyìsi.",ar:"هذه الحصة ممتعة جداً."}},

  {id:103, zh:"电影院", pinyin:"diànyǐngyuàn",pos:"noun",     meaning:"سينما",                           exZh:"我们去电影院。",           exPinyin:"Wǒmen qù diànyǐngyuàn.",         exEn:"We go to the cinema.", s2:{zh:"你可以帮我吗？",py:"Nǐ kěyǐ bāng wǒ ma?",ar:"هل يمكنك مساعدتي؟"}, s3:{zh:"这里可以吃东西吗？",py:"Zhèlǐ kěyǐ chī dōngxi ma?",ar:"هل يمكن الأكل هنا؟"}},

  {id:104, zh:"弟弟",   pinyin:"dìdi",        pos:"noun",     meaning:"الأخ الأصغر",                     exZh:"我弟弟在家。",            exPinyin:"Wǒ dìdi zài jiā.",               exEn:"My younger brother is at home.", s2:{zh:"请喝一口水。",py:"Qǐng hē yī kǒu shuǐ.",ar:"تفضل اشرب رشفة ماء."}, s3:{zh:"这孩子有一张大嘴巴。",py:"Zhè háizi yǒu yī zhāng dà zuǐba.",ar:"هذا الطفل لديه فم كبير."}},

  {id:105, zh:"东西",   pinyin:"dōngxi",      pos:"noun",     meaning:"شيء / أشياء",                     exZh:"我买了东西。",            exPinyin:"Wǒ mǎi le dōngxi.",              exEn:"I bought some things.", s2:{zh:"给我一块蛋糕。",py:"Gěi wǒ yī kuài dàngāo.",ar:"أعطني قطعة كعك."}, s3:{zh:"这块肉多少钱？",py:"Zhè kuài ròu duōshao qián?",ar:"كم ثمن هذه القطعة من اللحم؟"}},

  {id:106, zh:"都",     pinyin:"dōu",         pos:"adverb",   meaning:"كلهم / جميعًا",                   exZh:"我们都是学生。",           exPinyin:"Wǒmen dōu shì xuéshēng.",        exEn:"We are all students.", s2:{zh:"请你来我家玩。",py:"Qǐng nǐ lái wǒ jiā wán.",ar:"أدعوك للمجيء إلى منزلي للعب."}, s3:{zh:"他下周来北京。",py:"Tā xià zhōu lái Běijīng.",ar:"هو قادم إلى بكين الأسبوع القادم."}},

  {id:107, zh:"读",     pinyin:"dú",          pos:"verb",     meaning:"يقرأ",                            exZh:"我读书。",                exPinyin:"Wǒ dú shū.",                     exEn:"I read books.", s2:{zh:"老师对我很好。",py:"Lǎoshī duì wǒ hěn hǎo.",ar:"المعلم يعاملني بشكل جيد."}, s3:{zh:"我喜欢我的老师。",py:"Wǒ xǐhuan wǒ de lǎoshī.",ar:"أنا أحب معلمي."}},

  {id:108, zh:"读书",   pinyin:"dúshū",       pos:"verb",     meaning:"يدرس / يتعلم",                    exZh:"我在读书。",              exPinyin:"Wǒ zài dúshū.",                  exEn:"I am studying.", s2:{zh:"我吃了早饭就去上学。",py:"Wǒ chīle zǎofàn jiù qù shàngxué.",ar:"بعد تناول الفطور ذهبت إلى المدرسة."}, s3:{zh:"他走了吗？——走了。",py:"Tā zǒu le ma? —— Zǒu le.",ar:"هل ذهب؟ — نعم، ذهب."}},

  {id:109, zh:"二",     pinyin:"èr",          pos:"numeral",  meaning:"اثنان",                           exZh:"我有二本书。",            exPinyin:"Wǒ yǒu èr běn shū.",             exEn:"I have two books.", s2:{zh:"今天很冷，多穿衣服。",py:"Jīntiān hěn lěng, duō chuān yīfu.",ar:"الجو بارد اليوم، البس ملابس أكثر."}, s3:{zh:"冬天很冷，夏天很热。",py:"Dōngtiān hěn lěng, xiàtiān hěn rè.",ar:"الشتاء بارد والصيف حار."}},

  {id:110, zh:"饭",     pinyin:"fàn",         pos:"noun",     meaning:"وجبة / طعام",                     exZh:"我吃饭。",                exPinyin:"Wǒ chī fàn.",                    exEn:"I eat a meal.", s2:{zh:"书在包里，不是在桌子上。",py:"Shū zài bāo lǐ, bú shì zài zhuōzi shàng.",ar:"الكتاب في الحقيبة، وليس على الطاولة."}, s3:{zh:"冰箱里有水果。",py:"Bīngxiāng lǐ yǒu shuǐguǒ.",ar:"في الثلاجة فاكهة."}},

  {id:111, zh:"饭店",   pinyin:"fàndiàn",     pos:"noun",     meaning:"مطعم",                            exZh:"我们去饭店吃饭。",         exPinyin:"Wǒmen qù fàndiàn chī fàn.",      exEn:"We go to a restaurant to eat.", s2:{zh:"我有两本中文书。",py:"Wǒ yǒu liǎng běn Zhōngwén shū.",ar:"لدي كتابان بالصينية."}, s3:{zh:"两个人去买菜。",py:"Liǎng gè rén qù mǎi cài.",ar:"شخصان ذهبا لشراء الخضار."}},

  {id:112, zh:"房间",   pinyin:"fángjiān",    pos:"noun",     meaning:"غرفة",                            exZh:"这个房间很小。",           exPinyin:"Zhège fángjiān hěn xiǎo.",       exEn:"This room is small.", s2:{zh:"现在是零点，该睡觉了。",py:"Xiànzài shì líng diǎn, gāi shuìjiào le.",ar:"الآن منتصف الليل، حان وقت النوم."}, s3:{zh:"零度很冷。",py:"Líng dù hěn lěng.",ar:"صفر درجة بارد جداً."}},

  {id:113, zh:"非常",   pinyin:"fēicháng",    pos:"adverb",   meaning:"جداً / للغاية",                   exZh:"我非常高兴。",            exPinyin:"Wǒ fēicháng gāoxìng.",           exEn:"I'm very happy.", s2:{zh:"他有六个姐妹。",py:"Tā yǒu liù gè jiěmèi.",ar:"لديه ست أخوات."}, s3:{zh:"六点我就起床了。",py:"Liù diǎn wǒ jiù qǐchuáng le.",ar:"استيقظت في السادسة."}},

  {id:114, zh:"飞机",   pinyin:"fēijī",       pos:"noun",     meaning:"طائرة",                           exZh:"我坐飞机。",              exPinyin:"Wǒ zuò fēijī.",                  exEn:"I take a plane.", s2:{zh:"你吃饭了吗？",py:"Nǐ chī fàn le ma?",ar:"هل أكلت؟"}, s3:{zh:"你是中国人吗？",py:"Nǐ shì Zhōngguó rén ma?",ar:"هل أنت صيني؟"}},

  {id:115, zh:"分",     pinyin:"fēn",         pos:"noun",     meaning:"دقيقة",                           exZh:"现在五分。",              exPinyin:"Xiànzài wǔ fēn.",                exEn:"It's five minutes past.", s2:{zh:"他在超市卖水果。",py:"Tā zài chāoshì mài shuǐguǒ.",ar:"يبيع الفاكهة في السوبرماركت."}, s3:{zh:"这本书卖多少钱？",py:"Zhè běn shū mài duōshao qián?",ar:"بكم يباع هذا الكتاب؟"}},

  {id:116, zh:"分钟",   pinyin:"fēnzhōng",    pos:"particle", meaning:"دقيقة (وحدة وقت)",               exZh:"十分钟以后。",            exPinyin:"Shí fēnzhōng yǐhòu.",            exEn:"After ten minutes.", s2:{zh:"我去超市买苹果和香蕉。",py:"Wǒ qù chāoshì mǎi píngguǒ hé xiāngjiāo.",ar:"ذهبت إلى السوبرماركت لشراء التفاح والموز."}, s3:{zh:"你帮我买一瓶水。",py:"Nǐ bāng wǒ mǎi yī píng shuǐ.",ar:"اشترِ لي زجاجة ماء من فضلك."}},

  {id:117, zh:"歌",     pinyin:"gē",          pos:"noun",     meaning:"أغنية",                           exZh:"我听歌。",                exPinyin:"Wǒ tīng gē.",                    exEn:"I listen to songs.", s2:{zh:"我妈妈在家吃早饭。",py:"Wǒ māma zài jiā chī zǎofàn.",ar:"أمي تتناول الفطور في البيت."}, s3:{zh:"妈妈做的饭很好吃。",py:"Māma zuò de fàn hěn hǎochī.",ar:"طبخ أمي لذيذ جداً."}},

  {id:118, zh:"给",     pinyin:"gěi",         pos:"verb",     meaning:"يعطي",                            exZh:"我给你书。",              exPinyin:"Wǒ gěi nǐ shū.",                 exEn:"I give you a book.", s2:{zh:"你看起来很忙，有事吗？",py:"Nǐ kàn qǐlái hěn máng, yǒu shì ma?",ar:"تبدو مشغولاً، هل هناك شيء ما؟"}, s3:{zh:"今天我没有时间，明天吧。",py:"Jīntiān wǒ méiyǒu shíjiān, míngtiān ba.",ar:"ليس لدي وقت اليوم، لنقل غداً."}},

  {id:119, zh:"公司",   pinyin:"gōngsī",      pos:"noun",     meaning:"شركة",                            exZh:"他在公司工作。",           exPinyin:"Tā zài gōngsī gōngzuò.",         exEn:"He works at a company.", s2:{zh:"她家里有一只小猫。",py:"Tā jiālǐ yǒu yī zhī xiǎo māo.",ar:"في منزلها قطة صغيرة."}, s3:{zh:"这只猫很可爱。",py:"Zhè zhī māo hěn kě'ài.",ar:"هذه القطة لطيفة جداً."}},

  {id:120, zh:"狗",     pinyin:"gǒu",         pos:"noun",     meaning:"كلب",                             exZh:"我有一只狗。",            exPinyin:"Wǒ yǒu yì zhī gǒu.",             exEn:"I have a dog.", s2:{zh:"没关系，我还有时间。",py:"Méi guānxi, wǒ hái yǒu shíjiān.",ar:"لا بأس، لا يزال لدي وقت."}, s3:{zh:"迟到没关系，来就好。",py:"Chídào méi guānxi, lái jiù hǎo.",ar:"التأخر لا يهم، المهم أنك أتيت."}},

  {id:121, zh:"贵",     pinyin:"guì",         pos:"adjective",meaning:"غالي السعر",                      exZh:"这个很贵。",              exPinyin:"Zhège hěn guì.",                  exEn:"This is expensive.", s2:{zh:"我妹妹在小学读书。",py:"Wǒ mèimei zài xiǎoxué dúshū.",ar:"أختي الصغرى تدرس في المرحلة الابتدائية."}, s3:{zh:"妹妹，来吃晚饭了。",py:"Mèimei, lái chī wǎnfàn le.",ar:"أختي، تعالي لتناول العشاء."}},

  {id:122, zh:"好吃",   pinyin:"hǎochī",      pos:"adjective",meaning:"لذيذ",                            exZh:"这个菜很好吃。",           exPinyin:"Zhège cài hěn hǎochī.",          exEn:"This dish is delicious.", s2:{zh:"没事，别担心了。",py:"Méishì, bié dānxīn le.",ar:"لا يهم، لا تقلق."}, s3:{zh:"你没事吧？",py:"Nǐ méishì ba?",ar:"هل أنت بخير؟"}},

  {id:123, zh:"好看",   pinyin:"hǎokàn",      pos:"adjective",meaning:"جميل المنظر",                     exZh:"这本书很好看。",           exPinyin:"Zhè běn shū hěn hǎokàn.",        exEn:"This book looks good.", s2:{zh:"你有没有时间？",py:"Nǐ yǒu méiyǒu shíjiān?",ar:"هل لديك وقت أم لا؟"}, s3:{zh:"我没有钱，不能去旅游。",py:"Wǒ méiyǒu qián, bù néng qù lǚyóu.",ar:"ليس لدي مال، لا أستطيع السفر."}},

  {id:124, zh:"好听",   pinyin:"hǎotīng",     pos:"adjective",meaning:"جميل الصوت",                      exZh:"这首歌很好听。",           exPinyin:"Zhè shǒu gē hěn hǎotīng.",       exEn:"This song sounds nice.", s2:{zh:"老师们都很好。",py:"Lǎoshīmen dōu hěn hǎo.",ar:"كل المعلمين طيبون."}, s3:{zh:"同学们，上课了！",py:"Tóngxuémen, shàngkè le!",ar:"أيها الطلاب، حان وقت الدرس!"}},

  {id:125, zh:"好玩儿", pinyin:"hǎowánr",     pos:"adjective",meaning:"ممتع / مسلٍّ",                    exZh:"这个游戏很好玩儿。",       exPinyin:"Zhège yóuxì hěn hǎowánr.",       exEn:"This game is fun.", s2:{zh:"早上我吃面包和鸡蛋。",py:"Zǎoshang wǒ chī miànbāo hé jīdàn.",ar:"في الصباح آكل خبزاً وبيضاً."}, s3:{zh:"你喜欢吃面包吗？",py:"Nǐ xǐhuan chī miànbāo ma?",ar:"هل تحب أكل الخبز؟"}},

  {id:126, zh:"喝",     pinyin:"hē",          pos:"verb",     meaning:"يشرب",                            exZh:"我喝水。",                exPinyin:"Wǒ hē shuǐ.",                    exEn:"I drink water.", s2:{zh:"我最喜欢吃面条儿。",py:"Wǒ zuì xǐhuan chī miàntiáor.",ar:"أحب النودلز أكثر من أي شيء."}, s3:{zh:"面条儿好吃极了！",py:"Miàntiáor hǎochī jí le!",ar:"النودلز لذيذة جداً جداً!"}},

  {id:127, zh:"后",     pinyin:"hòu",         pos:"noun",     meaning:"بعد",                             exZh:"下课后。",                exPinyin:"Xiàkè hòu.",                     exEn:"After class.", s2:{zh:"中午我吃米饭和菜。",py:"Zhōngwǔ wǒ chī mǐfàn hé cài.",ar:"في الظهيرة آكل الأرز مع الأطباق."}, s3:{zh:"你今天吃米饭还是面条？",py:"Nǐ jīntiān chī mǐfàn háishi miàntiáo?",ar:"هل تأكل اليوم أرزاً أم نودلز؟"}},

  {id:128, zh:"回",     pinyin:"huí",         pos:"verb",     meaning:"يعود",                            exZh:"我回家。",                exPinyin:"Wǒ huí jiā.",                    exEn:"I go home.", s2:{zh:"明年我去中国留学。",py:"Míngnián wǒ qù Zhōngguó liúxué.",ar:"العام القادم سأذهب للدراسة في الصين."}, s3:{zh:"明年你做什么打算？",py:"Míngnián nǐ zuò shénme dǎsuàn?",ar:"ما خططك للعام القادم؟"}},

  {id:129, zh:"会",     pinyin:"huì",         pos:"verb",     meaning:"يستطيع / يعرف كيف",               exZh:"我会说汉语。",            exPinyin:"Wǒ huì shuō Hànyǔ.",             exEn:"I can speak Chinese.", s2:{zh:"明天是星期一，要上课。",py:"Míngtiān shì xīngqīyī, yào shàngkè.",ar:"غداً الاثنين، يجب أن نحضر الدرس."}, s3:{zh:"明天天气怎么样？",py:"Míngtiān tiānqì zěnmeyàng?",ar:"كيف سيكون الطقس غداً؟"}},

  {id:130, zh:"火车",   pinyin:"huǒchē",      pos:"noun",     meaning:"قطار",                            exZh:"我坐火车。",              exPinyin:"Wǒ zuò huǒchē.",                 exEn:"I take the train.", s2:{zh:"你叫什么名字？",py:"Nǐ jiào shénme míngzi?",ar:"ما اسمك؟"}, s3:{zh:"请写下你的名字。",py:"Qǐng xiě xià nǐ de míngzi.",ar:"اكتب اسمك من فضلك."}},

  {id:131, zh:"汉语",   pinyin:"Hànyǔ",       pos:"noun",     meaning:"اللغة الصينية (المندرين)",        exZh:"我学汉语。",              exPinyin:"Wǒ xué Hànyǔ.",                  exEn:"I study Chinese.", s2:{zh:"那本书是你的吗？",py:"Nà běn shū shì nǐ de ma?",ar:"هل ذلك الكتاب لك؟"}, s3:{zh:"那个人是谁？",py:"Nàge rén shì shéi?",ar:"من ذلك الشخص؟"}},

  {id:132, zh:"汉字",   pinyin:"Hànzì",       pos:"noun",     meaning:"الحرف الصيني",                    exZh:"我写汉字。",              exPinyin:"Wǒ xiě Hànzì.",                  exEn:"I write Chinese characters.", s2:{zh:"哪本书最有意思？",py:"Nǎ běn shū zuì yǒuyìsi?",ar:"أي كتاب الأكثر إثارة للاهتمام؟"}, s3:{zh:"哪个是你的？",py:"Nǎge shì nǐ de?",ar:"أيّها لك؟"}},

  {id:133, zh:"号",     pinyin:"hào",         pos:"noun",     meaning:"رقم / تاريخ",                     exZh:"今天是三号。",            exPinyin:"Jīntiān shì sān hào.",           exEn:"Today is the third.", s2:{zh:"他在那边等你。",py:"Tā zài nàbiān děng nǐ.",ar:"هو ينتظرك هناك."}, s3:{zh:"书店在那边。",py:"Shūdiàn zài nàbiān.",ar:"المكتبة هناك."}},

  {id:134, zh:"见",     pinyin:"jiàn",        pos:"verb",     meaning:"يرى / يلتقي",                     exZh:"我见老师。",              exPinyin:"Wǒ jiàn lǎoshī.",                exEn:"I see the teacher.", s2:{zh:"我要买那个红色的。",py:"Wǒ yào mǎi nàge hóngsè de.",ar:"أريد شراء ذلك الأحمر."}, s3:{zh:"那个很好看。",py:"Nàge hěn hǎokàn.",ar:"ذلك يبدو جميلاً."}},

  {id:135, zh:"件",     pinyin:"jiàn",        pos:"particle", meaning:"(عداد للملابس)",                  exZh:"一件衣服。",              exPinyin:"Yí jiàn yīfu.",                  exEn:"One piece of clothing.", s2:{zh:"你要哪个？这个还是那个？",py:"Nǐ yào nǎge? Zhège háishi nàge?",ar:"أيّها تريد؟ هذا أم ذاك؟"}, s3:{zh:"哪个便宜？",py:"Nǎge piányí?",ar:"أيّها أرخص؟"}},

  {id:136, zh:"饺子",   pinyin:"jiǎozi",      pos:"noun",     meaning:"زلابية (جياوزي)",                 exZh:"我吃饺子。",              exPinyin:"Wǒ chī jiǎozi.",                 exEn:"I eat dumplings.", s2:{zh:"我以前住在那里。",py:"Wǒ yǐqián zhù zài nàlǐ.",ar:"كنت أسكن هناك من قبل."}, s3:{zh:"那里的冬天很冷。",py:"Nàlǐ de dōngtiān hěn lěng.",ar:"الشتاء هناك بارد جداً."}},

  {id:137, zh:"家人",   pinyin:"jiārén",      pos:"noun",     meaning:"أفراد الأسرة",                    exZh:"我的家人在中国。",         exPinyin:"Wǒ de jiārén zài Zhōngguó.",     exEn:"My family is in China.", s2:{zh:"你去哪里了？",py:"Nǐ qù nǎlǐ le?",ar:"أين ذهبت؟"}, s3:{zh:"超市在哪里？",py:"Chāoshì zài nǎlǐ?",ar:"أين السوبرماركت؟"}},

  {id:138, zh:"鸡蛋",   pinyin:"jīdàn",       pos:"noun",     meaning:"بيضة",                            exZh:"我吃鸡蛋。",              exPinyin:"Wǒ chī jīdàn.",                  exEn:"I eat eggs.", s2:{zh:"他是一位男医生。",py:"Tā shì yī wèi nán yīshēng.",ar:"هو طبيب رجل."}, s3:{zh:"班里有几个男生？",py:"Bān lǐ yǒu jǐ gè nánshēng?",ar:"كم طالباً في الفصل؟"}},

  {id:139, zh:"今天",   pinyin:"jīntiān",     pos:"noun",     meaning:"اليوم",                           exZh:"今天星期五。",            exPinyin:"Jīntiān xīngqīwǔ.",              exEn:"Today is Friday.", s2:{zh:"他的男朋友很高。",py:"Tā de nánpéngyou hěn gāo.",ar:"حبيبها طويل جداً."}, s3:{zh:"你有男朋友吗？",py:"Nǐ yǒu nánpéngyou ma?",ar:"هل لديك حبيب؟"}},

  {id:140, zh:"九",     pinyin:"jiǔ",         pos:"numeral",  meaning:"تسعة",                            exZh:"我有九个学生。",           exPinyin:"Wǒ yǒu jiǔ gè xuéshēng.",       exEn:"I have nine students.", s2:{zh:"老师在那儿等我们。",py:"Lǎoshī zài nàr děng wǒmen.",ar:"المعلم ينتظرنا هناك."}, s3:{zh:"书在那儿，去拿吧。",py:"Shū zài nàr, qù ná ba.",ar:"الكتاب هناك، اذهب وخذه."}},

  {id:141, zh:"觉得",   pinyin:"juéde",       pos:"verb",     meaning:"يشعر / يعتقد",                    exZh:"我觉得很好。",            exPinyin:"Wǒ juéde hěn hǎo.",              exEn:"I think it's very good.", s2:{zh:"你住在哪儿？",py:"Nǐ zhù zài nǎr?",ar:"أين تسكن؟"}, s3:{zh:"卫生间在哪儿？",py:"Wèishēngjiān zài nǎr?",ar:"أين الحمام؟"}},

  {id:142, zh:"开",     pinyin:"kāi",         pos:"verb",     meaning:"يفتح",                            exZh:"老师开门。",              exPinyin:"Lǎoshī kāi mén.",                exEn:"The teacher opens the door.", s2:{zh:"我喜欢这些书，不喜欢那些。",py:"Wǒ xǐhuan zhèxiē shū, bù xǐhuan nàxiē.",ar:"أحب هذه الكتب، لا أحب تلك."}, s3:{zh:"那些苹果多少钱？",py:"Nàxiē píngguǒ duōshao qián?",ar:"بكم تلك التفاحات؟"}},

  {id:143, zh:"开车",   pinyin:"kāichē",      pos:"verb",     meaning:"يقود السيارة",                    exZh:"他开车去公司。",           exPinyin:"Tā kāichē qù gōngsī.",           exEn:"He drives to the company.", s2:{zh:"你要哪些书？",py:"Nǐ yào nǎxiē shū?",ar:"أيّ الكتب تريد؟"}, s3:{zh:"哪些学生来了？",py:"Nǎxiē xuéshēng lái le?",ar:"أيّ الطلاب جاؤوا؟"}},

  {id:144, zh:"看",     pinyin:"kàn",         pos:"verb",     meaning:"ينظر / يشاهد",                    exZh:"我看书。",                exPinyin:"Wǒ kàn shū.",                    exEn:"I read a book.", s2:{zh:"你吃饭了，他呢？",py:"Nǐ chī fàn le, tā ne?",ar:"لقد أكلت، وهو؟"}, s3:{zh:"我很好，你呢？",py:"Wǒ hěn hǎo, nǐ ne?",ar:"أنا بخير، وأنت؟"}},

  {id:145, zh:"看病",   pinyin:"kànbìng",     pos:"verb",     meaning:"يزور الطبيب",                     exZh:"他去看病。",              exPinyin:"Tā qù kànbìng.",                 exEn:"He goes to see a doctor.", s2:{zh:"我能帮你拿书。",py:"Wǒ néng bāng nǐ ná shū.",ar:"أستطيع مساعدتك في حمل الكتب."}, s3:{zh:"你能不能来帮我？",py:"Nǐ néng bù néng lái bāng wǒ?",ar:"هل تستطيع المجيء لمساعدتي؟"}},

  {id:146, zh:"看见",   pinyin:"kànjiàn",     pos:"verb",     meaning:"يرى / شاهد",                      exZh:"我看见老师了。",           exPinyin:"Wǒ kànjiàn lǎoshī le.",          exEn:"I saw the teacher.", s2:{zh:"你也是学生吗？",py:"Nǐ yě shì xuéshēng ma?",ar:"هل أنت أيضاً طالب؟"}, s3:{zh:"你喜欢什么运动？",py:"Nǐ xǐhuan shénme yùndòng?",ar:"ما الرياضة التي تحبها؟"}},

  {id:147, zh:"课",     pinyin:"kè",          pos:"noun",     meaning:"درس / حصة",                       exZh:"今天有一节课。",           exPinyin:"Jīntiān yǒu yì jié kè.",         exEn:"There is one class today.", s2:{zh:"你好！我叫李明。",py:"Nǐ hǎo! Wǒ jiào Lǐ Míng.",ar:"مرحباً! اسمي لي مينغ."}, s3:{zh:"你好，欢迎来中国！",py:"Nǐ hǎo, huānyíng lái Zhōngguó!",ar:"مرحباً، أهلاً وسهلاً بك في الصين!"}},

  {id:148, zh:"可以",   pinyin:"kěyǐ",        pos:"verb",     meaning:"يمكن / يجوز",                     exZh:"我可以去。",              exPinyin:"Wǒ kěyǐ qù.",                    exEn:"I can go.", s2:{zh:"我学中文已经两年了。",py:"Wǒ xué Zhōngwén yǐjīng liǎng nián le.",ar:"لقد مضى عامان على دراستي الصينية."}, s3:{zh:"新年快乐！",py:"Xīnnián kuàilè!",ar:"كل عام وأنتم بخير!"}},

  {id:149, zh:"块",     pinyin:"kuài",        pos:"particle", meaning:"(عداد) قطعة",                     exZh:"一块蛋糕。",              exPinyin:"Yí kuài dàngāo.",                exEn:"One piece of cake.", s2:{zh:"你们都是学生吗？",py:"Nǐmen dōu shì xuéshēng ma?",ar:"هل كلكم طلاب؟"}, s3:{zh:"你们从哪里来？",py:"Nǐmen cóng nǎlǐ lái?",ar:"من أين أنتم؟"}},

  {id:150, zh:"来",     pinyin:"lái",         pos:"verb",     meaning:"يأتي",                            exZh:"你来学校吗？",            exPinyin:"Nǐ lái xuéxiào ma?",             exEn:"Are you coming to school?", s2:{zh:"您好，请问您贵姓？",py:"Nín hǎo, qǐngwèn nín guìxìng?",ar:"مرحباً، ما اسم عائلتك؟"}, s3:{zh:"您喝点什么？",py:"Nín hē diǎn shénme?",ar:"ماذا تشرب؟"}},

  {id:151, zh:"了",     pinyin:"le",          pos:"particle", meaning:"(أداة إتمام الفعل)",              exZh:"我吃了饭。",              exPinyin:"Wǒ chī le fàn.",                 exEn:"I ate a meal.", s2:{zh:"早上我喝一杯牛奶。",py:"Zǎoshang wǒ hē yī bēi niúnǎi.",ar:"في الصباح أشرب كوباً من الحليب."}, s3:{zh:"你喜欢喝牛奶还是喝茶？",py:"Nǐ xǐhuan hē niúnǎi háishi hē chá?",ar:"هل تحب الحليب أم الشاي؟"}},

  {id:152, zh:"冷",     pinyin:"lěng",        pos:"adjective",meaning:"بارد",                            exZh:"今天很冷。",              exPinyin:"Jīntiān hěn lěng.",              exEn:"It is cold today.", s2:{zh:"他是一位女医生。",py:"Tā shì yī wèi nǚ yīshēng.",ar:"هي طبيبة."}, s3:{zh:"这是女生的房间。",py:"Zhè shì nǚshēng de fángjiān.",ar:"هذه غرفة البنات."}},

  {id:153, zh:"里",     pinyin:"lǐ",          pos:"noun",     meaning:"داخل / في",                       exZh:"书在包里。",              exPinyin:"Shū zài bāo lǐ.",                exEn:"The book is in the bag.", s2:{zh:"她的女儿很可爱。",py:"Tā de nǚ'ér hěn kě'ài.",ar:"ابنتها لطيفة جداً."}, s3:{zh:"他有一个女儿和一个儿子。",py:"Tā yǒu yī gè nǚ'ér hé yī gè érzi.",ar:"لديه ابنة وابن."}},

  {id:154, zh:"两",     pinyin:"liǎng",       pos:"numeral",  meaning:"اثنان (مع عداد)",                 exZh:"我有两本书。",            exPinyin:"Wǒ yǒu liǎng běn shū.",          exEn:"I have two books.", s2:{zh:"他的女朋友是日本人。",py:"Tā de nǚpéngyou shì Rìběn rén.",ar:"حبيبته يابانية."}, s3:{zh:"你女朋友叫什么？",py:"Nǐ nǚpéngyou jiào shénme?",ar:"ما اسم حبيبتك؟"}},

  {id:155, zh:"零",     pinyin:"líng",        pos:"numeral",  meaning:"صفر",                             exZh:"现在是零点。",            exPinyin:"Xiànzài shì líng diǎn.",         exEn:"It's zero o'clock.", s2:{zh:"这位女士是我的老师。",py:"Zhè wèi nǚshì shì wǒ de lǎoshī.",ar:"هذه السيدة هي معلمتي."}, s3:{zh:"女士们，请进。",py:"Nǚshìmen, qǐng jìn.",ar:"تفضلن أيتها السيدات."}},

  {id:156, zh:"六",     pinyin:"liù",         pos:"numeral",  meaning:"ستة",                             exZh:"我有六个朋友。",           exPinyin:"Wǒ yǒu liù gè péngyou.",         exEn:"I have six friends.", s2:{zh:"他是我最好的朋友。",py:"Tā shì wǒ zuì hǎo de péngyou.",ar:"هو أفضل أصدقائي."}, s3:{zh:"你有几个好朋友？",py:"Nǐ yǒu jǐ gè hǎo péngyou?",ar:"كم لديك من الأصدقاء المقربين؟"}},

  {id:157, zh:"卖",     pinyin:"mài",         pos:"verb",     meaning:"يبيع",                            exZh:"他卖书。",                exPinyin:"Tā mài shū.",                    exEn:"He sells books.", s2:{zh:"这件衣服很便宜，我买了。",py:"Zhè jiàn yīfu hěn piányí, wǒ mǎi le.",ar:"هذه الملابس رخيصة، اشتريتها."}, s3:{zh:"哪个便宜？",py:"Nǎge piányí?",ar:"أيّها أرخص؟"}},

  {id:158, zh:"买",     pinyin:"mǎi",         pos:"verb",     meaning:"يشتري",                           exZh:"我买苹果。",              exPinyin:"Wǒ mǎi píngguǒ.",                exEn:"I buy apples.", s2:{zh:"这个城市很漂亮。",py:"Zhège chéngshì hěn piàoliang.",ar:"هذه المدينة جميلة جداً."}, s3:{zh:"她穿的裙子很漂亮。",py:"Tā chuān de qúnzi hěn piàoliang.",ar:"الفستان الذي ترتديه جميل."}},

  {id:159, zh:"面包",   pinyin:"miànbāo",     pos:"noun",     meaning:"خبز",                             exZh:"我吃面包。",              exPinyin:"Wǒ chī miànbāo.",                exEn:"I eat bread.", s2:{zh:"我每天吃苹果。",py:"Wǒ měitiān chī píngguǒ.",ar:"آكل التفاح كل يوم."}, s3:{zh:"这些苹果很甜。",py:"Zhèxiē píngguǒ hěn tián.",ar:"هذه التفاحات حلوة جداً."}},

  {id:160, zh:"面条儿", pinyin:"miàntiáor",   pos:"noun",     meaning:"مكرونة / نودلز",                   exZh:"我吃面条儿。",            exPinyin:"Wǒ chī miàntiáor.",              exEn:"I eat noodles.", s2:{zh:"他有七本中文书。",py:"Tā yǒu qī běn Zhōngwén shū.",ar:"لديه سبعة كتب صينية."}, s3:{zh:"七点半上课。",py:"Qī diǎn bàn shàngkè.",ar:"الدرس في السابعة والنصف."}},

  {id:161, zh:"米饭",   pinyin:"mǐfàn",       pos:"noun",     meaning:"أرز مطبوخ",                       exZh:"我吃米饭。",              exPinyin:"Wǒ chī mǐfàn.",                  exEn:"I eat rice.", s2:{zh:"他在我的前边坐着。",py:"Tā zài wǒ de qián biān zuòzhe.",ar:"هو جالس أمامي."}, s3:{zh:"前边有一家超市。",py:"Qiánbiān yǒu yī jiā chāoshì.",ar:"يوجد سوبرماركت في الأمام."}},

  {id:162, zh:"明年",   pinyin:"míngnián",    pos:"noun",     meaning:"العام القادم",                    exZh:"明年我去中国。",           exPinyin:"Míngnián wǒ qù Zhōngguó.",       exEn:"I will go to China next year.", s2:{zh:"我今天有很多钱。",py:"Wǒ jīntiān yǒu hěn duō qián.",ar:"لدي كثير من المال اليوم."}, s3:{zh:"这件衣服多少钱？",py:"Zhè jiàn yīfu duōshao qián?",ar:"كم ثمن هذه الملابس؟"}},

  {id:163, zh:"明天",   pinyin:"míngtiān",    pos:"noun",     meaning:"غداً",                            exZh:"明天上课。",              exPinyin:"Míngtiān shàngkè.",              exEn:"There is class tomorrow.", s2:{zh:"这本书一千元，太贵了！",py:"Zhè běn shū yì qiān yuán, tài guì le!",ar:"هذا الكتاب بألف يوان، غالٍ جداً!"}, s3:{zh:"公司有一千名员工。",py:"Gōngsī yǒu yì qiān míng yuángōng.",ar:"الشركة لديها ألف موظف."}},

  {id:164, zh:"那",     pinyin:"nà",          pos:"pronoun",  meaning:"ذلك / تلك",                       exZh:"那是我的书。",            exPinyin:"Nà shì wǒ de shū.",              exEn:"That is my book.", s2:{zh:"我每天七点起床。",py:"Wǒ měitiān qī diǎn qǐchuáng.",ar:"أستيقظ في السابعة كل يوم."}, s3:{zh:"你今天几点起床了？",py:"Nǐ jīntiān jǐ diǎn qǐchuáng le?",ar:"في أي ساعة استيقظت اليوم؟"}},

  {id:165, zh:"那边",   pinyin:"nàbiān",      pos:"pronoun",  meaning:"هناك / في ذلك الجانب",            exZh:"他在那边。",              exPinyin:"Tā zài nàbiān.",                 exEn:"He is over there.", s2:{zh:"请坐，请喝茶。",py:"Qǐng zuò, qǐng hē chá.",ar:"اجلس من فضلك، اشرب الشاي."}, s3:{zh:"请大家安静一下。",py:"Qǐng dàjiā ānjìng yīxià.",ar:"الرجاء من الجميع الهدوء قليلاً."}},

  {id:166, zh:"那个",   pinyin:"nàge",        pos:"pronoun",  meaning:"ذلك الشيء",                       exZh:"我买那个。",              exPinyin:"Wǒ mǎi nàge.",                   exEn:"I buy that one.", s2:{zh:"请问，哪里有超市？",py:"Qǐngwèn, nǎlǐ yǒu chāoshì?",ar:"عفواً، أين يوجد سوبرماركت؟"}, s3:{zh:"请问，现在几点？",py:"Qǐngwèn, xiànzài jǐ diǎn?",ar:"عفواً، كم الساعة الآن؟"}},

  {id:167, zh:"哪个",   pinyin:"nǎge",        pos:"pronoun",  meaning:"أي واحد؟",                        exZh:"你要哪个？",              exPinyin:"Nǐ yào nǎge?",                   exEn:"Which one do you want?", s2:{zh:"我每天去学校上课。",py:"Wǒ měitiān qù xuéxiào shàngkè.",ar:"أذهب للمدرسة كل يوم لحضور الدروس."}, s3:{zh:"你去哪儿了？",py:"Nǐ qù nǎr le?",ar:"أين ذهبت؟"}},

  {id:168, zh:"那里",   pinyin:"nàlǐ",        pos:"pronoun",  meaning:"هناك",                            exZh:"我住在那里。",            exPinyin:"Wǒ zhù zài nàlǐ.",               exEn:"I live there.", s2:{zh:"去年我在中国学习。",py:"Qùnián wǒ zài Zhōngguó xuéxí.",ar:"العام الماضي كنت أدرس في الصين."}, s3:{zh:"去年你做什么了？",py:"Qùnián nǐ zuò shénme le?",ar:"ماذا فعلت العام الماضي؟"}},

  {id:169, zh:"哪里",   pinyin:"nǎlǐ",        pos:"pronoun",  meaning:"أين؟",                            exZh:"你去哪里？",              exPinyin:"Nǐ qù nǎlǐ?",                   exEn:"Where are you going?", s2:{zh:"今天天气很热。",py:"Jīntiān tiānqì hěn rè.",ar:"الجو حار جداً اليوم."}, s3:{zh:"喝点热水暖暖身体。",py:"Hē diǎn rè shuǐ nuǎnnuǎn shēntǐ.",ar:"اشرب بعض الماء الساخن لتدفئة جسمك."}},

  {id:170, zh:"男",     pinyin:"nán",         pos:"adjective",meaning:"ذكر",                             exZh:"他是男老师。",            exPinyin:"Tā shì nán lǎoshī.",             exEn:"He is a male teacher.", s2:{zh:"他是个好人，大家都喜欢他。",py:"Tā shì gè hǎo rén, dàjiā dōu xǐhuan tā.",ar:"هو شخص طيب، الجميع يحبه."}, s3:{zh:"中国有十四亿人。",py:"Zhōngguó yǒu shísì yì rén.",ar:"في الصين مليار وأربعمائة مليون شخص."}},

  {id:171, zh:"男朋友", pinyin:"nánpéngyou",  pos:"noun",     meaning:"صديق / حبيب",                     exZh:"她有男朋友。",            exPinyin:"Tā yǒu nánpéngyou.",             exEn:"She has a boyfriend.", s2:{zh:"我认识他，我们以前见过。",py:"Wǒ rènshi tā, wǒmen yǐqián jiàn guò.",ar:"أعرفه، التقينا من قبل."}, s3:{zh:"你认识几个汉字？",py:"Nǐ rènshi jǐ gè Hànzì?",ar:"كم حرفاً صينياً تعرف؟"}},

  {id:172, zh:"那儿",   pinyin:"nàr",         pos:"pronoun",  meaning:"هناك",                            exZh:"他在那儿。",              exPinyin:"Tā zài nàr.",                    exEn:"He is there.", s2:{zh:"今天是三月三日。",py:"Jīntiān shì sān yuè sān rì.",ar:"اليوم هو الثالث من مارس."}, s3:{zh:"他的生日是几月几日？",py:"Tā de shēngrì shì jǐ yuè jǐ rì?",ar:"في أي شهر ويوم ميلاده؟"}},

  {id:173, zh:"哪儿",   pinyin:"nǎr",         pos:"pronoun",  meaning:"أين؟",                            exZh:"你住在哪儿？",            exPinyin:"Nǐ zhù zài nǎr?",                exEn:"Where do you live?", s2:{zh:"一加一等于三？不对！",py:"Yī jiā yī děngyú sān? Bú duì!",ar:"واحد زائد واحد يساوي ثلاثة؟ خطأ!"}, s3:{zh:"我有三只猫。",py:"Wǒ yǒu sān zhī māo.",ar:"لدي ثلاث قطط."}},

  {id:174, zh:"那些",   pinyin:"nàxiē",       pos:"pronoun",  meaning:"تلك (الأشياء)",                   exZh:"我喜欢那些书。",           exPinyin:"Wǒ xǐhuan nàxiē shū.",           exEn:"I like those books.", s2:{zh:"请上车，谢谢！",py:"Qǐng shàng chē, xièxie!",ar:"تفضل بالصعود إلى السيارة، شكراً!"}, s3:{zh:"你上几年级了？",py:"Nǐ shàng jǐ niánjí le?",ar:"في أي صف أنت الآن؟"}},

  {id:175, zh:"哪些",   pinyin:"nǎxiē",       pos:"pronoun",  meaning:"أيّها؟",                          exZh:"你要哪些？",              exPinyin:"Nǐ yào nǎxiē?",                  exEn:"Which ones do you want?", s2:{zh:"我八点上班，五点下班。",py:"Wǒ bā diǎn shàngbān, wǔ diǎn xiàbān.",ar:"أبدأ العمل في الثامنة وأنتهي في الخامسة."}, s3:{zh:"你几点上班？",py:"Nǐ jǐ diǎn shàngbān?",ar:"في أي ساعة تبدأ العمل؟"}},

  {id:176, zh:"能",     pinyin:"néng",        pos:"verb",     meaning:"يستطيع / قادر على",               exZh:"我能来。",                exPinyin:"Wǒ néng lái.",                   exEn:"I can come.", s2:{zh:"附近有一家商店。",py:"Fùjìn yǒu yī jiā shāngdiàn.",ar:"هناك متجر قريب من هنا."}, s3:{zh:"我去商店买水果。",py:"Wǒ qù shāngdiàn mǎi shuǐguǒ.",ar:"ذهبت إلى المتجر لشراء الفاكهة."}},

  {id:177, zh:"年",     pinyin:"nián",        pos:"noun",     meaning:"سنة / عام",                       exZh:"我学汉语两年。",           exPinyin:"Wǒ xué Hànyǔ liǎng nián.",       exEn:"I have studied Chinese for two years.", s2:{zh:"我们八点上课，十二点下课。",py:"Wǒmen bā diǎn shàngkè, shí'èr diǎn xiàkè.",ar:"نبدأ الدرس في الثامنة وننهيه في الثانية عشرة."}, s3:{zh:"今天上课了吗？",py:"Jīntiān shàngkè le ma?",ar:"هل كان هناك درس اليوم؟"}},

  {id:178, zh:"牛奶",   pinyin:"niúnǎi",      pos:"noun",     meaning:"حليب",                            exZh:"我喝牛奶。",              exPinyin:"Wǒ hē niúnǎi.",                  exEn:"I drink milk.", s2:{zh:"上午我在图书馆学习。",py:"Shàngwǔ wǒ zài túshūguǎn xuéxí.",ar:"في الصباح أدرس في المكتبة."}, s3:{zh:"上午九点见面。",py:"Shàngwǔ jiǔ diǎn jiànmiàn.",ar:"نلتقي في التاسعة صباحاً."}},

  {id:179, zh:"女",     pinyin:"nǚ",          pos:"adjective",meaning:"أنثى",                            exZh:"她是女老师。",            exPinyin:"Tā shì nǚ lǎoshī.",              exEn:"She is a female teacher.", s2:{zh:"孩子八岁开始上学。",py:"Háizi bā suì kāishǐ shàngxué.",ar:"يبدأ الطفل الدراسة في سن الثامنة."}, s3:{zh:"明天是第一天上学。",py:"Míngtiān shì dì yī tiān shàngxué.",ar:"غداً هو أول يوم دراسة."}},

  {id:180, zh:"女士",   pinyin:"nǚshì",       pos:"noun",     meaning:"سيدة",                            exZh:"这位女士很好。",           exPinyin:"Zhè wèi nǚshì hěn hǎo.",         exEn:"This lady is very kind.", s2:{zh:"班里学生很少，只有十个。",py:"Bān lǐ xuéshēng hěn shǎo, zhǐ yǒu shí gè.",ar:"الطلاب في الفصل قليلون، عشرة فقط."}, s3:{zh:"他说话很少。",py:"Tā shuōhuà hěn shǎo.",ar:"هو قليل الكلام."}},

  {id:181, zh:"朋友",   pinyin:"péngyou",     pos:"noun",     meaning:"صديق",                            exZh:"他是我的朋友。",           exPinyin:"Tā shì wǒ de péngyou.",          exEn:"He is my friend.", s2:{zh:"谁是你的老师？",py:"Shéi shì nǐ de lǎoshī?",ar:"من هو معلمك؟"}, s3:{zh:"谁来了？",py:"Shéi lái le?",ar:"من جاء؟"}},

  {id:182, zh:"便宜",   pinyin:"piányi",      pos:"adjective",meaning:"رخيص",                            exZh:"这个很便宜。",            exPinyin:"Zhège hěn piányi.",               exEn:"This is cheap.", s2:{zh:"他感冒了，生病了。",py:"Tā gǎnmào le, shēngbìng le.",ar:"أصيب بالزكام، مرض."}, s3:{zh:"你生病了，要去看医生。",py:"Nǐ shēngbìng le, yào qù kàn yīshēng.",ar:"أنت مريض، يجب أن تذهب للطبيب."}},

  {id:183, zh:"漂亮",   pinyin:"piàoliang",   pos:"adjective",meaning:"جميل",                            exZh:"她很漂亮。",              exPinyin:"Tā hěn piàoliang.",               exEn:"She is beautiful.", s2:{zh:"你想要什么礼物？",py:"Nǐ xiǎng yào shénme lǐwù?",ar:"ما الهدية التي تريدها؟"}, s3:{zh:"这是什么意思？",py:"Zhè shì shénme yìsi?",ar:"ما معنى هذا؟"}},

  {id:184, zh:"苹果",   pinyin:"píngguǒ",     pos:"noun",     meaning:"تفاحة",                           exZh:"我吃苹果。",              exPinyin:"Wǒ chī píngguǒ.",                exEn:"I eat apples.", s2:{zh:"今天我有十节课，太多了！",py:"Jīntiān wǒ yǒu shí jié kè, tài duō le!",ar:"لدي اليوم عشر حصص، كثير جداً!"}, s3:{zh:"十月十号是国庆节。",py:"Shí yuè shí hào shì Guóqìng Jié.",ar:"العاشر من أكتوبر هو عيد الوطني."}},

  {id:185, zh:"七",     pinyin:"qī",          pos:"numeral",  meaning:"سبعة",                            exZh:"我有七本书。",            exPinyin:"Wǒ yǒu qī běn shū.",             exEn:"I have seven books.", s2:{zh:"这是一件大事！",py:"Zhè shì yī jiàn dà shì!",ar:"هذا أمر كبير!"}, s3:{zh:"你有什么事？",py:"Nǐ yǒu shénme shì?",ar:"ماذا تريد؟"}},

  {id:186, zh:"前",     pinyin:"qián",        pos:"noun",     meaning:"أمام / قبل",                      exZh:"他在我前边。",            exPinyin:"Tā zài wǒ qián biān.",           exEn:"He is in front of me.", s2:{zh:"他是一个好人。",py:"Tā shì yī gè hǎo rén.",ar:"هو شخص طيب."}, s3:{zh:"你是学生还是老师？",py:"Nǐ shì xuéshēng háishi lǎoshī?",ar:"هل أنت طالب أم معلم؟"}},

  {id:187, zh:"钱",     pinyin:"qián",        pos:"noun",     meaning:"مال / نقود",                      exZh:"我有钱。",                exPinyin:"Wǒ yǒu qián.",                   exEn:"I have money.", s2:{zh:"吃饭的时候不要玩手机。",py:"Chī fàn de shíhou bú yào wán shǒujī.",ar:"لا تلعب بهاتفك أثناء الأكل."}, s3:{zh:"上课的时候要认真听。",py:"Shàngkè de shíhou yào rènzhēn tīng.",ar:"انتبه جيداً أثناء الدرس."}},

  {id:188, zh:"千",     pinyin:"qiān",        pos:"numeral",  meaning:"ألف",                             exZh:"这本书一千元。",           exPinyin:"Zhè běn shū yì qiān yuán.",      exEn:"This book costs one thousand yuan.", s2:{zh:"我没有时间休息。",py:"Wǒ méiyǒu shíjiān xiūxi.",ar:"ليس لدي وقت للراحة."}, s3:{zh:"你有时间吗？",py:"Nǐ yǒu shíjiān ma?",ar:"هل لديك وقت؟"}},

  {id:189, zh:"起床",   pinyin:"qǐchuáng",    pos:"verb",     meaning:"يستيقظ / ينهض",                   exZh:"我七点起床。",            exPinyin:"Wǒ qī diǎn qǐchuáng.",           exEn:"I get up at seven.", s2:{zh:"我的手机号是多少？",py:"Wǒ de shǒujī hào shì duōshao?",ar:"ما رقم هاتفي؟"}, s3:{zh:"手机没电了！",py:"Shǒujī méidiàn le!",ar:"بطارية الهاتف نفدت!"}},

  {id:190, zh:"请",     pinyin:"qǐng",        pos:"verb",     meaning:"من فضلك / يدعو",                  exZh:"请坐。",                  exPinyin:"Qǐng zuò.",                      exEn:"Please sit down.", s2:{zh:"这本书很有意思。",py:"Zhè běn shū hěn yǒuyìsi.",ar:"هذا الكتاب ممتع جداً."}, s3:{zh:"我在图书馆看书。",py:"Wǒ zài túshūguǎn kàn shū.",ar:"أقرأ الكتب في المكتبة."}},

  {id:191, zh:"去",     pinyin:"qù",          pos:"verb",     meaning:"يذهب",                            exZh:"我去学校。",              exPinyin:"Wǒ qù xuéxiào.",                 exEn:"I go to school.", s2:{zh:"附近有没有书店？",py:"Fùjìn yǒu méiyǒu shūdiàn?",ar:"هل يوجد دكان كتب قريب؟"}, s3:{zh:"我在书店买了很多书。",py:"Wǒ zài shūdiàn mǎile hěn duō shū.",ar:"اشتريت كتباً كثيرة من المكتبة."}},

  {id:192, zh:"去年",   pinyin:"qùnián",      pos:"noun",     meaning:"العام الماضي",                    exZh:"去年我学汉语。",           exPinyin:"Qùnián wǒ xué Hànyǔ.",           exEn:"Last year I studied Chinese.", s2:{zh:"我睡了八个小时。",py:"Wǒ shuì le bā gè xiǎoshí.",ar:"نمت ثماني ساعات."}, s3:{zh:"你昨晚睡得好吗？",py:"Nǐ zuówǎn shuì de hǎo ma?",ar:"هل نمت جيداً البارحة؟"}},

  {id:193, zh:"热",     pinyin:"rè",          pos:"adjective",meaning:"حار",                             exZh:"今天很热。",              exPinyin:"Jīntiān hěn rè.",                exEn:"It is hot today.", s2:{zh:"今天很热，喝点水吧。",py:"Jīntiān hěn rè, hē diǎn shuǐ ba.",ar:"الجو حار اليوم، اشرب بعض الماء."}, s3:{zh:"这杯水太热了！",py:"Zhè bēi shuǐ tài rè le!",ar:"هذا الكوب من الماء ساخن جداً!"}},

  {id:194, zh:"日",     pinyin:"rì",          pos:"noun",     meaning:"يوم / تاريخ",                     exZh:"三日见。",                exPinyin:"Sān rì jiàn.",                   exEn:"See you on the third.", s2:{zh:"我每天喝很多水。",py:"Wǒ měitiān hē hěn duō shuǐ.",ar:"أشرب كثيراً من الماء كل يوم."}, s3:{zh:"这杯水甜吗？",py:"Zhè bēi shuǐ tián ma?",ar:"هل هذا الكوب حلو؟"}},

  {id:195, zh:"三",     pinyin:"sān",         pos:"numeral",  meaning:"ثلاثة",                           exZh:"我有三个学生。",           exPinyin:"Wǒ yǒu sān gè xuéshēng.",       exEn:"I have three students.", s2:{zh:"我累了，想睡觉了。",py:"Wǒ lèi le, xiǎng shuìjiào le.",ar:"أنا متعب، أريد النوم."}, s3:{zh:"几点睡觉比较好？",py:"Jǐ diǎn shuìjiào bǐjiào hǎo?",ar:"في أي وقت يفضل النوم؟"}},

  {id:196, zh:"上",     pinyin:"shàng",       pos:"verb",     meaning:"يحضر / فوق",                      exZh:"我上课。",                exPinyin:"Wǒ shàng kè.",                   exEn:"I attend class.", s2:{zh:"他说中文说得很好。",py:"Tā shuō Zhōngwén shuō de hěn hǎo.",ar:"هو يتكلم الصينية بشكل جيد جداً."}, s3:{zh:"他们说你很聪明。",py:"Tāmen shuō nǐ hěn cōngming.",ar:"قالوا إنك ذكي."}},

  {id:197, zh:"上班",   pinyin:"shàngbān",    pos:"verb",     meaning:"يذهب للعمل",                      exZh:"我八点上班。",            exPinyin:"Wǒ bā diǎn shàngbān.",           exEn:"I go to work at eight.", s2:{zh:"你不要说话，听老师说。",py:"Nǐ bú yào shuōhuà, tīng lǎoshī shuō.",ar:"لا تتكلم، استمع إلى المعلم."}, s3:{zh:"在图书馆里不要说话。",py:"Zài túshūguǎn lǐ bú yào shuōhuà.",ar:"لا تتكلم في المكتبة."}},

  {id:198, zh:"商店",   pinyin:"shāngdiàn",   pos:"noun",     meaning:"متجر",                            exZh:"我去商店买东西。",         exPinyin:"Wǒ qù shāngdiàn mǎi dōngxi.",    exEn:"I go to the store to buy things.", s2:{zh:"他们四个人一起去了。",py:"Tāmen sì gè rén yīqǐ qù le.",ar:"الأربعة ذهبوا معاً."}, s3:{zh:"下午四点见。",py:"Xiàwǔ sì diǎn jiàn.",ar:"نلتقي في الرابعة مساءً."}},

  {id:199, zh:"上课",   pinyin:"shàngkè",     pos:"verb",     meaning:"يحضر الفصل",                      exZh:"我们上课。",              exPinyin:"Wǒmen shàngkè.",                 exEn:"We have class.", s2:{zh:"我们都是朋友。",py:"Wǒmen dōu shì péngyou.",ar:"كلنا أصدقاء."}, s3:{zh:"他们三个都喜欢踢足球。",py:"Tāmen sān gè dōu xǐhuan tī zúqiú.",ar:"الثلاثة يحبون كرة القدم."}},

  {id:200, zh:"上午",   pinyin:"shàngwǔ",     pos:"noun",     meaning:"الصباح (قبل الظهر)",              exZh:"上午我上课。",            exPinyin:"Shàngwǔ wǒ shàngkè.",            exEn:"I have class in the morning.", s2:{zh:"他是我的老师，也是我的朋友。",py:"Tā shì wǒ de lǎoshī, yě shì wǒ de péngyou.",ar:"هو معلمي وصديقي أيضاً."}, s3:{zh:"他们是朋友，不是家人。",py:"Tāmen shì péngyou, bú shì jiārén.",ar:"هم أصدقاء وليسوا عائلة."}},

  {id:201, zh:"上学",   pinyin:"shàngxué",    pos:"verb",     meaning:"يذهب للمدرسة",                    exZh:"孩子上学。",              exPinyin:"Háizi shàngxué.",                exEn:"The child goes to school.", s2:{zh:"明天是这个月的第一天。",py:"Míngtiān shì zhège yuè de dì yī tiān.",ar:"غداً هو أول يوم في هذا الشهر."}, s3:{zh:"今天是星期几？",py:"Jīntiān shì xīngqī jǐ?",ar:"ما يوم الأسبوع اليوم؟"}},

  {id:202, zh:"少",     pinyin:"shǎo",        pos:"adjective",meaning:"قليل",                            exZh:"人很少。",                exPinyin:"Rén hěn shǎo.",                  exEn:"There are few people.", s2:{zh:"今天天气好，出去走走吧。",py:"Jīntiān tiānqì hǎo, chūqù zǒuzou ba.",ar:"الطقس جيد اليوم، لنخرج للتجول."}, s3:{zh:"今天的天气真好！",py:"Jīntiān de tiānqì zhēn hǎo!",ar:"الطقس اليوم رائع فعلاً!"}},

  {id:203, zh:"生病",   pinyin:"shēngbìng",   pos:"verb",     meaning:"يمرض",                            exZh:"他生病了。",              exPinyin:"Tā shēngbìng le.",               exEn:"He got sick.", s2:{zh:"我喜欢听音乐。",py:"Wǒ xǐhuan tīng yīnyuè.",ar:"أحب الاستماع إلى الموسيقى."}, s3:{zh:"你喜欢听什么音乐？",py:"Nǐ xǐhuan tīng shénme yīnyuè?",ar:"ما نوع الموسيقى التي تحبها؟"}},

  {id:204, zh:"十",     pinyin:"shí",         pos:"numeral",  meaning:"عشرة",                            exZh:"我有十本书。",            exPinyin:"Wǒ yǒu shí běn shū.",            exEn:"I have ten books.", s2:{zh:"我没听见，再说一遍。",py:"Wǒ méi tīngjiàn, zài shuō yī biàn.",ar:"لم أسمع، قل مرة أخرى."}, s3:{zh:"你听见他说了什么吗？",py:"Nǐ tīngjiàn tā shuō le shénme ma?",ar:"هل سمعت ما قاله؟"}},

  {id:205, zh:"事",     pinyin:"shì",         pos:"noun",     meaning:"أمر / موضوع",                     exZh:"这是一件事。",            exPinyin:"Zhè shì yí jiàn shì.",           exEn:"This is a matter.", s2:{zh:"它是我的猫，叫小白。",py:"Tā shì wǒ de māo, jiào Xiǎo Bái.",ar:"هي قطتي، اسمها شياو باي."}, s3:{zh:"桌子上有一本书，它是我的。",py:"Zhuōzi shàng yǒu yī běn shū, tā shì wǒ de.",ar:"على الطاولة كتاب، هو كتابي."}},

  {id:206, zh:"时候",   pinyin:"shíhou",      pos:"noun",     meaning:"وقت / لحظة",                      exZh:"吃饭的时候。",            exPinyin:"Chī fàn de shíhou.",             exEn:"Mealtime.", s2:{zh:"他在教室外边玩。",py:"Tā zài jiàoshì wàibiān wán.",ar:"هو يلعب خارج الفصل."}, s3:{zh:"外边很冷，不要出去。",py:"Wàibian hěn lěng, bú yào chūqù.",ar:"الخارج بارد، لا تخرج."}},

  {id:207, zh:"时间",   pinyin:"shíjiān",     pos:"noun",     meaning:"وقت",                             exZh:"我没有时间。",            exPinyin:"Wǒ méiyǒu shíjiān.",             exEn:"I don't have time.", s2:{zh:"孩子在外边玩，别担心。",py:"Háizi zài wàibian wán, bié dānxīn.",ar:"الطفل يلعب في الخارج، لا تقلق."}, s3:{zh:"外边有很多人在等。",py:"Wàibian yǒu hěn duō rén zài děng.",ar:"هناك كثير من الناس ينتظرون في الخارج."}},

  {id:208, zh:"手机",   pinyin:"shǒujī",      pos:"noun",     meaning:"هاتف محمول",                      exZh:"我的手机在这儿。",         exPinyin:"Wǒ de shǒujī zài zhèr.",         exEn:"My phone is here.", s2:{zh:"周末我们一起去玩吧！",py:"Zhōumò wǒmen yīqǐ qù wán ba!",ar:"لنذهب للتسلية معاً في عطلة نهاية الأسبوع!"}, s3:{zh:"孩子们喜欢玩游戏。",py:"Háizimen xǐhuan wán yóuxì.",ar:"الأطفال يحبون اللعب."}},

  {id:209, zh:"书",     pinyin:"shū",         pos:"noun",     meaning:"كتاب",                            exZh:"我看书。",                exPinyin:"Wǒ kàn shū.",                    exEn:"I read a book.", s2:{zh:"今天很晚了，你回家吧。",py:"Jīntiān hěn wǎn le, nǐ huí jiā ba.",ar:"الوقت متأخر الليلة، ارجع إلى البيت."}, s3:{zh:"我回来晚了，对不起。",py:"Wǒ huí lái wǎn le, duìbuqǐ.",ar:"عدت متأخراً، أنا آسف."}},

  {id:210, zh:"书店",   pinyin:"shūdiàn",     pos:"noun",     meaning:"مكتبة بيع",                       exZh:"我去书店。",              exPinyin:"Wǒ qù shūdiàn.",                 exEn:"I go to the bookstore.", s2:{zh:"我喜欢在家吃晚饭。",py:"Wǒ xǐhuan zài jiā chī wǎnfàn.",ar:"أحب تناول العشاء في البيت."}, s3:{zh:"晚饭做好了，快来吃！",py:"Wǎnfàn zuò hǎo le, kuài lái chī!",ar:"العشاء جاهز، تعال بسرعة لتأكل!"}},

  {id:211, zh:"睡",     pinyin:"shuì",        pos:"verb",     meaning:"ينام",                            exZh:"我睡了。",                exPinyin:"Wǒ shuì le.",                    exEn:"I slept.", s2:{zh:"晚上好，你吃饭了吗？",py:"Wǎnshang hǎo, nǐ chī fàn le ma?",ar:"مساء الخير، هل أكلت؟"}, s3:{zh:"晚上我喜欢看书。",py:"Wǎnshang wǒ xǐhuan kàn shū.",ar:"في المساء أحب القراءة."}},

  {id:212, zh:"水",     pinyin:"shuǐ",        pos:"noun",     meaning:"ماء",                             exZh:"我喝水。",                exPinyin:"Wǒ hē shuǐ.",                    exEn:"I drink water.", s2:{zh:"有问题请问老师。",py:"Yǒu wèntí qǐng wèn lǎoshī.",ar:"إذا كان لديك سؤال اسأل المعلم."}, s3:{zh:"你想问什么？",py:"Nǐ xiǎng wèn shénme?",ar:"ماذا تريد أن تسأل؟"}},

  {id:213, zh:"水果",   pinyin:"shuǐguǒ",     pos:"noun",     meaning:"فاكهة",                           exZh:"我吃水果。",              exPinyin:"Wǒ chī shuǐguǒ.",                exEn:"I eat fruit.", s2:{zh:"这个问题很难，我不会。",py:"Zhège wèntí hěn nán, wǒ bú huì.",ar:"هذا السؤال صعب، لا أستطيع."}, s3:{zh:"有什么问题吗？",py:"Yǒu shénme wèntí ma?",ar:"هل هناك أي مشكلة؟"}},

  {id:214, zh:"睡觉",   pinyin:"shuìjiào",    pos:"verb",     meaning:"ينام",                            exZh:"我想睡觉。",              exPinyin:"Wǒ xiǎng shuìjiào.",             exEn:"I want to sleep.", s2:{zh:"我们有五本书。",py:"Wǒmen yǒu wǔ běn shū.",ar:"لدينا خمسة كتب."}, s3:{zh:"下午五点放学。",py:"Xiàwǔ wǔ diǎn fàngxué.",ar:"تنتهي المدرسة في الخامسة مساءً."}},

  {id:215, zh:"说",     pinyin:"shuō",        pos:"verb",     meaning:"يقول / يتكلم",                    exZh:"他说汉语。",              exPinyin:"Tā shuō Hànyǔ.",                 exEn:"He speaks Chinese.", s2:{zh:"我每天中午吃午饭。",py:"Wǒ měitiān zhōngwǔ chī wǔfàn.",ar:"آكل الغداء كل يوم في الظهيرة."}, s3:{zh:"你午饭吃了吗？",py:"Nǐ wǔfàn chī le ma?",ar:"هل تناولت غداءك؟"}},

  {id:216, zh:"说话",   pinyin:"shuōhuà",     pos:"verb",     meaning:"يتحدث / يتكلم",                   exZh:"不要说话。",              exPinyin:"Bú yào shuōhuà.",                exEn:"Don't talk.", s2:{zh:"下课了，我们去吃饭吧。",py:"Xiàkè le, wǒmen qù chī fàn ba.",ar:"انتهى الدرس، لنذهب لتناول الطعام."}, s3:{zh:"我下了车就回家。",py:"Wǒ xià le chē jiù huí jiā.",ar:"بعد نزولي من السيارة عدت إلى البيت."}},

  {id:217, zh:"四",     pinyin:"sì",          pos:"numeral",  meaning:"أربعة",                           exZh:"我有四个朋友。",           exPinyin:"Wǒ yǒu sì gè péngyou.",          exEn:"I have four friends.", s2:{zh:"今天下雨了，出门带伞。",py:"Jīntiān xià yǔ le, chūmén dài sǎn.",ar:"اليوم يمطر، خذ مظلة معك."}, s3:{zh:"下雨天不好玩儿。",py:"Xià yǔ tiān bù hǎowánr.",ar:"الأيام الممطرة غير ممتعة."}},

  {id:218, zh:"他们",   pinyin:"tāmen",       pos:"pronoun",  meaning:"هم (ذكور/مختلط)",                 exZh:"他们是朋友。",            exPinyin:"Tāmen shì péngyou.",             exEn:"They are friends.", s2:{zh:"我六点下班，然后回家。",py:"Wǒ liù diǎn xiàbān, ránhòu huí jiā.",ar:"أنهي العمل في السادسة ثم أعود للبيت."}, s3:{zh:"你今天几点下班？",py:"Nǐ jīntiān jǐ diǎn xiàbān?",ar:"في أي ساعة تنهي عملك اليوم؟"}},

  {id:219, zh:"它们",   pinyin:"tāmen",       pos:"pronoun",  meaning:"هم (الأشياء)",                    exZh:"它们在这儿。",            exPinyin:"Tāmen zài zhèr.",                exEn:"They are here.", s2:{zh:"下课了，大家可以休息。",py:"Xiàkè le, dàjiā kěyǐ xiūxi.",ar:"انتهى الدرس، يمكن للجميع الراحة."}, s3:{zh:"几点下课？",py:"Jǐ diǎn xiàkè?",ar:"في أي ساعة ينتهي الدرس؟"}},

  {id:220, zh:"她们",   pinyin:"tāmen",       pos:"pronoun",  meaning:"هن (إناث)",                       exZh:"她们在上课。",            exPinyin:"Tāmen zài shàngkè.",             exEn:"They are having class.", s2:{zh:"他想学中文，也想去中国旅游。",py:"Tā xiǎng xué Zhōngwén, yě xiǎng qù Zhōngguó lǚyóu.",ar:"يريد دراسة الصينية كما يريد السياحة في الصين."}, s3:{zh:"我想喝水，你呢？",py:"Wǒ xiǎng hē shuǐ, nǐ ne?",ar:"أريد شرب الماء، وأنت؟"}},

  {id:221, zh:"天",     pinyin:"tiān",        pos:"noun",     meaning:"يوم",                             exZh:"今天是第一天。",           exPinyin:"Jīntiān shì dì yī tiān.",        exEn:"Today is the first day.", s2:{zh:"你好，请问王先生在吗？",py:"Nǐ hǎo, qǐngwèn Wáng xiānsheng zài ma?",ar:"مرحباً، هل السيد وانغ موجود؟"}, s3:{zh:"他在哪儿工作？",py:"Tā zài nǎr gōngzuò?",ar:"أين يعمل؟"}},

  {id:222, zh:"天气",   pinyin:"tiānqì",      pos:"noun",     meaning:"طقس",                             exZh:"今天的天气很好。",         exPinyin:"Jīntiān de tiānqì hěn hǎo.",     exEn:"The weather today is very good.", s2:{zh:"现在几点了？",py:"Xiànzài jǐ diǎn le?",ar:"كم الساعة الآن؟"}, s3:{zh:"现在我在图书馆。",py:"Xiànzài wǒ zài túshūguǎn.",ar:"أنا الآن في المكتبة."}},

  {id:223, zh:"听",     pinyin:"tīng",        pos:"verb",     meaning:"يستمع",                           exZh:"我听音乐。",              exPinyin:"Wǒ tīng yīnyuè.",                exEn:"I listen to music.", s2:{zh:"这只猫很小，很可爱。",py:"Zhè zhī māo hěn xiǎo, hěn kě'ài.",ar:"هذه القطة صغيرة ولطيفة."}, s3:{zh:"我的书包很小。",py:"Wǒ de shūbāo hěn xiǎo.",ar:"حقيبتي المدرسية صغيرة."}},

  {id:224, zh:"听见",   pinyin:"tīngjiàn",    pos:"verb",     meaning:"يسمع",                            exZh:"我听见老师说话了。",       exPinyin:"Wǒ tīngjiàn lǎoshī shuōhuà le.", exEn:"I heard the teacher speak.", s2:{zh:"这个小朋友叫什么名字？",py:"Zhège xiǎopéngyou jiào shénme míngzi?",ar:"ما اسم هذا الطفل الصغير؟"}, s3:{zh:"小朋友，你几岁了？",py:"Xiǎopéngyou, nǐ jǐ suì le?",ar:"أيها الطفل، كم عمرك؟"}},

  {id:225, zh:"它",     pinyin:"tā",          pos:"pronoun",  meaning:"هو (لغير الإنسان)",               exZh:"它在桌子上。",            exPinyin:"Tā zài zhuōzi shàng.",           exEn:"It is on the table.", s2:{zh:"我学了一小时中文了。",py:"Wǒ xuéle yī xiǎoshí Zhōngwén le.",ar:"لقد درست الصينية لساعة."}, s3:{zh:"要走一个小时才能到。",py:"Yào zǒu yī gè xiǎoshí cái néng dào.",ar:"يستغرق المشي ساعة للوصول."}},

  {id:226, zh:"外",     pinyin:"wài",         pos:"noun",     meaning:"خارج",                            exZh:"他在外边。",              exPinyin:"Tā zài wài biān.",               exEn:"He is outside.", s2:{zh:"我弟弟在小学读三年级。",py:"Wǒ dìdi zài xiǎoxué dú sān niánjí.",ar:"أخي الأصغر في الصف الثالث الابتدائي."}, s3:{zh:"小学生应该多读书。",py:"Xiǎoxuéshēng yīnggāi duō dúshū.",ar:"يجب على طلاب المرحلة الابتدائية القراءة أكثر."}},

  {id:227, zh:"外边",   pinyin:"wàibian",     pos:"noun",     meaning:"في الخارج",                       exZh:"孩子在外边玩。",           exPinyin:"Háizi zài wàibian wán.",          exEn:"The child is playing outside.", s2:{zh:"他是一个小学生，还很小。",py:"Tā shì yī gè xiǎoxuéshēng, hái hěn xiǎo.",ar:"هو طالب ابتدائي، لا يزال صغيراً."}, s3:{zh:"小学生喜欢玩游戏。",py:"Xiǎoxuéshēng xǐhuan wán yóuxì.",ar:"طلاب المرحلة الابتدائية يحبون الألعاب."}},

  {id:228, zh:"玩",     pinyin:"wán",         pos:"verb",     meaning:"يلعب / يمرح",                     exZh:"我们一起玩。",            exPinyin:"Wǒmen yìqǐ wán.",                exEn:"We play together.", s2:{zh:"下午我有空，我们喝茶吧。",py:"Xiàwǔ wǒ yǒu kòng, wǒmen hē chá ba.",ar:"لدي وقت فراغ في فترة ما بعد الظهر، لنشرب الشاي."}, s3:{zh:"下午三点有课。",py:"Xiàwǔ sān diǎn yǒu kè.",ar:"هناك درس في الثالثة مساءً."}},

  {id:229, zh:"晚",     pinyin:"wǎn",         pos:"adjective",meaning:"متأخر",                           exZh:"今天很晚。",              exPinyin:"Jīntiān hěn wǎn.",               exEn:"It is late today.", s2:{zh:"我在学中文，你呢？",py:"Wǒ zài xué Zhōngwén, nǐ ne?",ar:"أنا أدرس الصينية، وأنت؟"}, s3:{zh:"你最想学什么？",py:"Nǐ zuì xiǎng xué shénme?",ar:"ما الذي تريد تعلمه أكثر؟"}},

  {id:230, zh:"晚饭",   pinyin:"wǎnfàn",      pos:"noun",     meaning:"عشاء",                            exZh:"我吃晚饭。",              exPinyin:"Wǒ chī wǎnfàn.",                 exEn:"I eat dinner.", s2:{zh:"今天下雪了！",py:"Jīntiān xià xuě le!",ar:"هطل الثلج اليوم!"}, s3:{zh:"北方冬天常常下雪。",py:"Běifāng dōngtiān chángcháng xià xuě.",ar:"كثيراً ما يتساقط الثلج في الشمال شتاءً."}},

  {id:231, zh:"晚上",   pinyin:"wǎnshang",    pos:"noun",     meaning:"المساء",                          exZh:"晚上我在家。",            exPinyin:"Wǎnshang wǒ zài jiā.",           exEn:"I am at home in the evening.", s2:{zh:"我学习汉语已经一年了。",py:"Wǒ xuéxí Hànyǔ yǐjīng yī nián le.",ar:"لقد مضى عام على دراستي للغة الصينية."}, s3:{zh:"在中国学习汉语很好。",py:"Zài Zhōngguó xuéxí Hànyǔ hěn hǎo.",ar:"دراسة الصينية في الصين رائعة."}},

  {id:232, zh:"问",     pinyin:"wèn",         pos:"verb",     meaning:"يسأل",                            exZh:"我问老师。",              exPinyin:"Wǒ wèn lǎoshī.",                 exEn:"I ask the teacher.", s2:{zh:"我在学校学习中文。",py:"Wǒ zài xuéxiào xuéxí Zhōngwén.",ar:"أدرس الصينية في المدرسة."}, s3:{zh:"你的学校大吗？",py:"Nǐ de xuéxiào dà ma?",ar:"هل مدرستك كبيرة؟"}},

  {id:233, zh:"问题",   pinyin:"wèntí",       pos:"noun",     meaning:"سؤال / مشكلة",                    exZh:"这个问题很简单。",         exPinyin:"Zhège wèntí hěn jiǎndān.",       exEn:"This question is very simple.", s2:{zh:"我要喝水，不要茶。",py:"Wǒ yào hē shuǐ, bú yào chá.",ar:"أريد شرب الماء، لا الشاي."}, s3:{zh:"你要买什么？",py:"Nǐ yào mǎi shénme?",ar:"ماذا تريد أن تشتري؟"}},

  {id:234, zh:"五",     pinyin:"wǔ",          pos:"numeral",  meaning:"خمسة",                            exZh:"我有五本书。",            exPinyin:"Wǒ yǒu wǔ běn shū.",             exEn:"I have five books.", s2:{zh:"我也去，一起吧！",py:"Wǒ yě qù, yīqǐ ba!",ar:"سأذهب أيضاً، لنذهب معاً!"}, s3:{zh:"我也不知道答案。",py:"Wǒ yě bù zhīdào dá'àn.",ar:"أنا أيضاً لا أعرف الجواب."}},

  {id:235, zh:"午饭",   pinyin:"wǔfàn",       pos:"noun",     meaning:"غداء",                            exZh:"我吃午饭。",              exPinyin:"Wǒ chī wǔfàn.",                  exEn:"I eat lunch.", s2:{zh:"我只有一本书。",py:"Wǒ zhǐyǒu yī běn shū.",ar:"لدي كتاب واحد فقط."}, s3:{zh:"一加一等于二。",py:"Yī jiā yī děngyú èr.",ar:"واحد زائد واحد يساوي اثنين."}},

  {id:236, zh:"下",     pinyin:"xià",         pos:"verb",     meaning:"ينزل / تحت",                      exZh:"我下车。",                exPinyin:"Wǒ xià chē.",                    exEn:"I get off the bus.", s2:{zh:"我吃了一半，剩下一半。",py:"Wǒ chīle yī bàn, shèng xià yī bàn.",ar:"أكلت نصف وبقي نصف."}, s3:{zh:"一半的学生来了。",py:"Yī bàn de xuéshēng lái le.",ar:"نصف الطلاب حضروا."}},

  {id:237, zh:"下雨",   pinyin:"xià yǔ",      pos:"fixed",    meaning:"تمطر",                            exZh:"今天下雨了。",            exPinyin:"Jīntiān xià yǔ le.",             exEn:"It is raining today.", s2:{zh:"我喝一点儿水就走。",py:"Wǒ hē yīdiǎnr shuǐ jiù zǒu.",ar:"سأشرب القليل من الماء ثم أذهب."}, s3:{zh:"我会说一点儿中文。",py:"Wǒ huì shuō yīdiǎnr Zhōngwén.",ar:"أستطيع التحدث ببعض الصينية."}},

  {id:238, zh:"下班",   pinyin:"xiàbān",      pos:"verb",     meaning:"ينهي العمل",                      exZh:"我六点下班。",            exPinyin:"Wǒ liù diǎn xiàbān.",            exEn:"I get off work at six.", s2:{zh:"我买了很多新衣服。",py:"Wǒ mǎile hěn duō xīn yīfu.",ar:"اشتريت كثيراً من الملابس الجديدة."}, s3:{zh:"你的衣服很好看。",py:"Nǐ de yīfu hěn hǎokàn.",ar:"ملابسك جميلة جداً."}},

  {id:239, zh:"下课",   pinyin:"xiàkè",       pos:"verb",     meaning:"تنتهي الحصة",                     exZh:"现在下课了。",            exPinyin:"Xiànzài xiàkè le.",              exEn:"Class is over now.", s2:{zh:"他是医生，在医院工作。",py:"Tā shì yīshēng, zài yīyuàn gōngzuò.",ar:"هو طبيب، يعمل في المستشفى."}, s3:{zh:"我妈妈是医生。",py:"Wǒ māma shì yīshēng.",ar:"أمي طبيبة."}},

  {id:240, zh:"先生",   pinyin:"xiānsheng",   pos:"noun",     meaning:"سيد / الأستاذ",                   exZh:"王先生很好。",            exPinyin:"Wáng xiānsheng hěn hǎo.",        exEn:"Mr. Wang is very nice.", s2:{zh:"等一下，我来了！",py:"Děng yīxià, wǒ lái le!",ar:"انتظر لحظة، أنا قادم!"}, s3:{zh:"请等一下，我打电话。",py:"Qǐng děng yīxià, wǒ dǎ diànhuà.",ar:"انتظر لحظة من فضلك، أجري مكالمة."}},

  {id:241, zh:"现在",   pinyin:"xiànzài",     pos:"noun",     meaning:"الآن",                            exZh:"现在几点？",              exPinyin:"Xiànzài jǐ diǎn?",               exEn:"What time is it now?", s2:{zh:"我买了一些水果和蔬菜。",py:"Wǒ mǎile yīxiē shuǐguǒ hé shūcài.",ar:"اشتريت بعض الفاكهة والخضار."}, s3:{zh:"给你一些苹果。",py:"Gěi nǐ yīxiē píngguǒ.",ar:"خذ بعض التفاح."}},

  {id:242, zh:"小",     pinyin:"xiǎo",        pos:"adjective",meaning:"صغير",                            exZh:"这只猫很小。",            exPinyin:"Zhè zhī māo hěn xiǎo.",          exEn:"This cat is very small.", s2:{zh:"我爸爸在医院工作。",py:"Wǒ bàba zài yīyuàn gōngzuò.",ar:"أبي يعمل في المستشفى."}, s3:{zh:"他住院了，在医院休息。",py:"Tā zhùyuàn le, zài yīyuàn xiūxi.",ar:"دخل المستشفى، يستريح هناك."}},

  {id:243, zh:"小朋友", pinyin:"xiǎopéngyou", pos:"noun",     meaning:"طفل صغير",                        exZh:"这个小朋友很可爱。",       exPinyin:"Zhège xiǎopéngyou hěn kě'ài.",   exEn:"This child is very cute.", s2:{zh:"请坐在椅子上等一下。",py:"Qǐng zuò zài yǐzi shàng děng yīxià.",ar:"اجلس على الكرسي وانتظر لحظة."}, s3:{zh:"椅子在桌子旁边。",py:"Yǐzi zài zhuōzi pángbiān.",ar:"الكرسي بجانب الطاولة."}},

  {id:244, zh:"小时",   pinyin:"xiǎoshí",     pos:"noun",     meaning:"ساعة (وقت)",                      exZh:"我学了一小时。",           exPinyin:"Wǒ xué le yì xiǎoshí.",          exEn:"I studied for one hour.", s2:{zh:"我们有时间，一起出去吧。",py:"Wǒmen yǒu shíjiān, yīqǐ chūqù ba.",ar:"لدينا وقت، لنخرج معاً."}, s3:{zh:"你有时间帮我吗？",py:"Nǐ yǒu shíjiān bāng wǒ ma?",ar:"هل لديك وقت لمساعدتي؟"}},

  {id:245, zh:"小学",   pinyin:"xiǎoxué",     pos:"noun",     meaning:"مدرسة ابتدائية",                  exZh:"他在小学学习。",           exPinyin:"Tā zài xiǎoxué xuéxí.",          exEn:"He studies at a primary school.", s2:{zh:"有的学生来了，有的还没来。",py:"Yǒude xuéshēng lái le, yǒude hái méi lái.",ar:"بعض الطلاب أتوا والبعض لم يأتِ بعد."}, s3:{zh:"有的人喜欢热天，有的人喜欢冷天。",py:"Yǒude rén xǐhuan rè tiān, yǒude rén xǐhuan lěng tiān.",ar:"بعض الناس يحبون الجو الحار والبعض يحب البارد."}},

  {id:246, zh:"小学生", pinyin:"xiǎoxuéshēng",pos:"noun",     meaning:"تلميذ ابتدائي",                   exZh:"她是小学生。",             exPinyin:"Tā shì xiǎoxuéshēng.",           exEn:"She is a primary school student.", s2:{zh:"我有些不舒服，想休息。",py:"Wǒ yǒuxiē bù shūfu, xiǎng xiūxi.",ar:"أشعر ببعض الانزعاج، أريد الراحة."}, s3:{zh:"他有些不高兴。",py:"Tā yǒuxiē bù gāoxìng.",ar:"هو غير سعيد قليلاً."}},

  {id:247, zh:"下午",   pinyin:"xiàwǔ",       pos:"noun",     meaning:"بعد الظهر",                       exZh:"下午我上班。",            exPinyin:"Xiàwǔ wǒ shàngbān.",             exEn:"I work in the afternoon.", s2:{zh:"今天有点儿冷，多穿一件。",py:"Jīntiān yǒudiǎnr lěng, duō chuān yī jiàn.",ar:"الجو بارد نوعاً ما اليوم، البس قطعة ملابس إضافية."}, s3:{zh:"这个有点儿贵，有没有便宜的？",py:"Zhège yǒudiǎnr guì, yǒu méiyǒu piányí de?",ar:"هذا غالٍ قليلاً، هل يوجد ما هو أرخص؟"}},

  {id:248, zh:"写",     pinyin:"xiě",         pos:"verb",     meaning:"يكتب",                            exZh:"我写汉字。",              exPinyin:"Wǒ xiě Hànzì.",                  exEn:"I write Chinese characters.", s2:{zh:"外边有雨，别出去了。",py:"Wàibian yǒu yǔ, bié chūqù le.",ar:"المطر في الخارج، لا تخرج."}, s3:{zh:"下雨了，我不去了。",py:"Xià yǔ le, wǒ bú qù le.",ar:"تمطر، لن أذهب."}},

  {id:249, zh:"些",     pinyin:"xiē",         pos:"particle", meaning:"(عداد) بعض",                      exZh:"一些书。",                exPinyin:"Yìxiē shū.",                     exEn:"Some books.", s2:{zh:"苹果一个五元，十个五十元。",py:"Píngguǒ yī gè wǔ yuán, shí gè wǔshí yuán.",ar:"التفاحة بخمسة يوان، وعشرة تفاحات بخمسين يوان."}, s3:{zh:"这本书二十元。",py:"Zhè běn shū èrshí yuán.",ar:"هذا الكتاب بعشرين يوان."}},

  {id:250, zh:"喜欢",   pinyin:"xǐhuan",      pos:"verb",     meaning:"يُحبّ / يُفضّل",                   exZh:"我喜欢汉语。",            exPinyin:"Wǒ xǐhuan Hànyǔ.",               exEn:"I like Chinese.", s2:{zh:"这个月我很忙。",py:"Zhège yuè wǒ hěn máng.",ar:"أنا مشغول جداً هذا الشهر."}, s3:{zh:"你几月生日？",py:"Nǐ jǐ yuè shēngrì?",ar:"في أي شهر ميلادك؟"}},

  {id:251, zh:"新",     pinyin:"xīn",         pos:"adjective",meaning:"جديد",                            exZh:"这是新书。",              exPinyin:"Zhè shì xīn shū.",               exEn:"This is a new book.", s2:{zh:"请再说一遍，谢谢。",py:"Qǐng zài shuō yī biàn, xièxie.",ar:"قل مرة أخرى من فضلك، شكراً."}, s3:{zh:"我再也不迟到了！",py:"Wǒ zài yě bù chídào le!",ar:"لن أتأخر مرة أخرى!"}},

  {id:252, zh:"星期",   pinyin:"xīngqī",      pos:"noun",     meaning:"أسبوع",                           exZh:"这个星期很忙。",           exPinyin:"Zhège xīngqī hěn máng.",         exEn:"This week is very busy.", s2:{zh:"我在家，你来我家吧。",py:"Wǒ zài jiā, nǐ lái wǒ jiā ba.",ar:"أنا في البيت، تعال إلى منزلي."}, s3:{zh:"他在学校上课。",py:"Tā zài xuéxiào shàngkè.",ar:"هو في المدرسة يدرس."}},

  {id:253, zh:"星期日", pinyin:"xīngqīrì",    pos:"noun",     meaning:"الأحد",                           exZh:"星期日我休息。",           exPinyin:"Xīngqīrì wǒ xiūxi.",             exEn:"I rest on Sunday.", s2:{zh:"今天起得很早，六点就起床了。",py:"Jīntiān qǐ de hěn zǎo, liù diǎn jiù qǐchuáng le.",ar:"استيقظت مبكراً اليوم، في السادسة."}, s3:{zh:"你今天起得早吗？",py:"Nǐ jīntiān qǐ de zǎo ma?",ar:"هل استيقظت مبكراً اليوم؟"}},

  {id:254, zh:"星期天", pinyin:"xīngqītiān",  pos:"noun",     meaning:"الأحد",                           exZh:"星期天见。",              exPinyin:"Xīngqītiān jiàn.",               exEn:"See you on Sunday.", s2:{zh:"我每天早饭吃鸡蛋和面包。",py:"Wǒ měitiān zǎofàn chī jīdàn hé miànbāo.",ar:"في الفطور آكل البيض والخبز كل يوم."}, s3:{zh:"你吃早饭了吗？",py:"Nǐ chī zǎofàn le ma?",ar:"هل تناولت فطورك؟"}},

  {id:255, zh:"休息",   pinyin:"xiūxi",       pos:"verb",     meaning:"يرتاح",                           exZh:"我想休息。",              exPinyin:"Wǒ xiǎng xiūxi.",                exEn:"I want to rest.", s2:{zh:"早上好！你吃早饭了吗？",py:"Zǎoshang hǎo! Nǐ chī zǎofàn le ma?",ar:"صباح الخير! هل تناولت فطورك؟"}, s3:{zh:"我每天早上七点起床。",py:"Wǒ měitiān zǎoshang qī diǎn qǐchuáng.",ar:"أستيقظ في السابعة كل صباح."}},

  {id:256, zh:"学",     pinyin:"xué",         pos:"verb",     meaning:"يتعلم / يدرس",                    exZh:"我学汉语。",              exPinyin:"Wǒ xué Hànyǔ.",                  exEn:"I study Chinese.", s2:{zh:"你怎么来学校的？",py:"Nǐ zěnme lái xuéxiào de?",ar:"كيف أتيت إلى المدرسة؟"}, s3:{zh:"这道菜怎么做？",py:"Zhè dào cài zěnme zuò?",ar:"كيف يُطبخ هذا الطبق؟"}},

  {id:257, zh:"雪",     pinyin:"xuě",         pos:"noun",     meaning:"ثلج",                             exZh:"下雪了。",                exPinyin:"Xià xuě le.",                    exEn:"It is snowing.", s2:{zh:"这家餐厅怎么样？",py:"Zhè jiā cāntīng zěnmeyàng?",ar:"كيف هذا المطعم؟"}, s3:{zh:"这个主意怎么样？",py:"Zhège zhǔyì zěnmeyàng?",ar:"كيف هذه الفكرة؟"}},

  {id:258, zh:"学习",   pinyin:"xuéxí",       pos:"verb",     meaning:"يتعلم / يدرس",                    exZh:"我学习汉语。",            exPinyin:"Wǒ xuéxí Hànyǔ.",                exEn:"I study Chinese.", s2:{zh:"我找不到我的书了！",py:"Wǒ zhǎo bú dào wǒ de shū le!",ar:"لا أجد كتابي!"}, s3:{zh:"你在找谁？",py:"Nǐ zài zhǎo shéi?",ar:"من تبحث عنه؟"}},

  {id:259, zh:"学校",   pinyin:"xuéxiào",     pos:"noun",     meaning:"مدرسة",                           exZh:"我在学校学习。",           exPinyin:"Wǒ zài xuéxiào xuéxí.",          exEn:"I study at school.", s2:{zh:"这是谁的东西？",py:"Zhè shì shéi de dōngxi?",ar:"هذه أغراض من؟"}, s3:{zh:"这是我的手机。",py:"Zhè shì wǒ de shǒujī.",ar:"هذا هاتفي."}},

  {id:260, zh:"要",     pinyin:"yào",         pos:"verb",     meaning:"يريد",                            exZh:"我要喝水。",              exPinyin:"Wǒ yào hē shuǐ.",                exEn:"I want to drink water.", s2:{zh:"我在这边，快来！",py:"Wǒ zài zhèbiān, kuài lái!",ar:"أنا هنا، تعال بسرعة!"}, s3:{zh:"书店在这边。",py:"Shūdiàn zài zhèbiān.",ar:"المكتبة في هذه الجهة."}},

  {id:261, zh:"一",     pinyin:"yī",          pos:"numeral",  meaning:"واحد",                            exZh:"我有一本书。",            exPinyin:"Wǒ yǒu yī běn shū.",             exEn:"I have one book.", s2:{zh:"我要买这个，不要那个。",py:"Wǒ yào mǎi zhège, bú yào nàge.",ar:"أريد شراء هذا وليس ذاك."}, s3:{zh:"这个菜好吃吗？",py:"Zhège cài hǎochī ma?",ar:"هل هذا الطبق لذيذ؟"}},

  {id:262, zh:"一半",   pinyin:"yíbàn",       pos:"numeral",  meaning:"نصف",                             exZh:"我吃了一半。",            exPinyin:"Wǒ chī le yíbàn.",               exEn:"I ate half.", s2:{zh:"我就住在这里，不远。",py:"Wǒ jiù zhù zài zhèlǐ, bù yuǎn.",ar:"أسكن هنا، ليس بعيداً."}, s3:{zh:"这里有很多商店。",py:"Zhèlǐ yǒu hěn duō shāngdiàn.",ar:"هناك كثير من المتاجر هنا."}},

  {id:263, zh:"一点儿", pinyin:"yìdiǎnr",     pos:"particle", meaning:"قليلاً",                          exZh:"我喝一点儿水。",           exPinyin:"Wǒ hē yìdiǎnr shuǐ.",            exEn:"I drink a little water.", s2:{zh:"真好！谢谢你！",py:"Zhēn hǎo! Xièxie nǐ!",ar:"رائع فعلاً! شكراً لك!"}, s3:{zh:"这道菜真好吃！",py:"Zhè dào cài zhēn hǎochī!",ar:"هذا الطبق لذيذ فعلاً!"}},

  {id:264, zh:"衣服",   pinyin:"yīfu",        pos:"noun",     meaning:"ملابس",                           exZh:"我买了衣服。",            exPinyin:"Wǒ mǎi le yīfu.",                exEn:"I bought clothes.", s2:{zh:"他正在做作业。",py:"Tā zhèngzài zuò zuòyè.",ar:"هو يؤدي واجبه الآن."}, s3:{zh:"我正在学习，等一下。",py:"Wǒ zhèngzài xuéxí, děng yīxià.",ar:"أنا أدرس الآن، انتظر لحظة."}},

  {id:265, zh:"医生",   pinyin:"yīshēng",     pos:"noun",     meaning:"طبيب",                            exZh:"他是医生。",              exPinyin:"Tā shì yīshēng.",                exEn:"He is a doctor.", s2:{zh:"我在这儿，你在哪儿？",py:"Wǒ zài zhèr, nǐ zài nǎr?",ar:"أنا هنا، أين أنت؟"}, s3:{zh:"书就在这儿，找到了！",py:"Shū jiù zài zhèr, zhǎodào le!",ar:"الكتاب هنا، وجدته!"}},

  {id:266, zh:"一下",   pinyin:"yíxià",       pos:"adverb",   meaning:"لحظة / قليلاً",                   exZh:"你等一下。",              exPinyin:"Nǐ děng yíxià.",                 exEn:"Wait a moment.", s2:{zh:"我喜欢这些，不喜欢那些。",py:"Wǒ xǐhuan zhèxiē, bù xǐhuan nàxiē.",ar:"أحب هذه ولا أحب تلك."}, s3:{zh:"这些书都是你的吗？",py:"Zhèxiē shū dōu shì nǐ de ma?",ar:"هل كل هذه الكتب لك؟"}},

  {id:267, zh:"一些",   pinyin:"yìxiē",       pos:"particle", meaning:"بعض",                             exZh:"我买了一些水果。",         exPinyin:"Wǒ mǎi le yìxiē shuǐguǒ.",      exEn:"I bought some fruit.", s2:{zh:"这里只有一只猫。",py:"Zhèlǐ zhǐ yǒu yī zhī māo.",ar:"هنا قطة واحدة فقط."}, s3:{zh:"他有两只狗和一只猫。",py:"Tā yǒu liǎng zhī gǒu hé yī zhī māo.",ar:"لديه كلبان وقطة."}},

  {id:268, zh:"医院",   pinyin:"yīyuàn",      pos:"noun",     meaning:"مستشفى",                          exZh:"他在医院。",              exPinyin:"Tā zài yīyuàn.",                 exEn:"He is in the hospital.", s2:{zh:"我知道答案了！",py:"Wǒ zhīdào dá'àn le!",ar:"عرفت الإجابة!"}, s3:{zh:"你知道他在哪里吗？",py:"Nǐ zhīdào tā zài nǎlǐ ma?",ar:"هل تعرف أين هو؟"}},

  {id:269, zh:"椅子",   pinyin:"yǐzi",        pos:"noun",     meaning:"كرسي",                            exZh:"我坐在椅子上。",           exPinyin:"Wǒ zuò zài yǐzi shàng.",         exEn:"I sit on the chair.", s2:{zh:"我明年要去中国。",py:"Wǒ míngnián yào qù Zhōngguó.",ar:"سأذهب إلى الصين العام القادم."}, s3:{zh:"中国是个大国。",py:"Zhōngguó shì gè dà guó.",ar:"الصين دولة كبيرة."}},

  {id:270, zh:"有的",   pinyin:"yǒude",       pos:"pronoun",  meaning:"بعضهم",                           exZh:"有的学生在学习。",         exPinyin:"Yǒude xuéshēng zài xuéxí.",      exEn:"Some students are studying.", s2:{zh:"我在学中文，也在学中国文化。",py:"Wǒ zài xué Zhōngwén, yě zài xué Zhōngguó wénhuà.",ar:"أدرس الصينية وأدرس الثقافة الصينية أيضاً."}, s3:{zh:"中文比英文难。",py:"Zhōngwén bǐ Yīngwén nán.",ar:"الصينية أصعب من الإنجليزية."}},

  {id:271, zh:"有些",   pinyin:"yǒuxiē",      pos:"pronoun",  meaning:"بعض / نوعاً ما",                  exZh:"我有些累。",              exPinyin:"Wǒ yǒuxiē lèi.",                 exEn:"I'm a bit tired.", s2:{zh:"现在是中午，该吃午饭了。",py:"Xiànzài shì zhōngwǔ, gāi chī wǔfàn le.",ar:"الآن وقت الظهيرة، حان وقت الغداء."}, s3:{zh:"中午好！",py:"Zhōngwǔ hǎo!",ar:"مرحباً وقت الظهيرة!"}},

  {id:272, zh:"有（一）点儿",pinyin:"yǒu diǎnr",pos:"adverb", meaning:"قليلاً / نوعاً ما",               exZh:"今天有点儿冷。",           exPinyin:"Jīntiān yǒudiǎnr lěng.",         exEn:"It's a little cold today.", s2:{zh:"他在中学学习，成绩很好。",py:"Tā zài zhōngxué xuéxí, chéngjī hěn hǎo.",ar:"يدرس في الثانوية وعلاماته ممتازة."}, s3:{zh:"中学生要努力学习。",py:"Zhōngxuéshēng yào nǔlì xuéxí.",ar:"يجب على طلاب الثانوية الدراسة بجد."}},

  {id:273, zh:"雨",     pinyin:"yǔ",          pos:"noun",     meaning:"مطر",                             exZh:"外边有雨。",              exPinyin:"Wàibian yǒu yǔ.",                exEn:"There is rain outside.", s2:{zh:"她的弟弟是中学生。",py:"Tā de dìdi shì zhōngxuéshēng.",ar:"أخوها الأصغر طالب ثانوي."}, s3:{zh:"中学生每天有很多作业。",py:"Zhōngxuéshēng měitiān yǒu hěn duō zuòyè.",ar:"طلاب الثانوية لديهم كثير من الواجبات يومياً."}},

  {id:274, zh:"元",     pinyin:"yuán",        pos:"particle", meaning:"يوان (عملة)",                     exZh:"十元。",                  exPinyin:"Shí yuán.",                      exEn:"Ten yuan.", s2:{zh:"我现在住在北京。",py:"Wǒ xiànzài zhù zài Běijīng.",ar:"أنا أسكن في بكين الآن."}, s3:{zh:"你住在哪个城市？",py:"Nǐ zhù zài nǎge chéngshì?",ar:"في أي مدينة تسكن؟"}},

  {id:275, zh:"月",     pinyin:"yuè",         pos:"noun",     meaning:"شهر",                             exZh:"这个月很忙。",            exPinyin:"Zhège yuè hěn máng.",            exEn:"This month is very busy.", s2:{zh:"书在桌子上，快去拿。",py:"Shū zài zhuōzi shàng, kuài qù ná.",ar:"الكتاب على الطاولة، اذهب وخذه بسرعة."}, s3:{zh:"桌子太小了，放不下。",py:"Zhuōzi tài xiǎo le, fàng bù xià.",ar:"الطاولة صغيرة جداً، لا تسع."}},

  {id:276, zh:"再",     pinyin:"zài",         pos:"adverb",   meaning:"مرة أخرى / ثانية",               exZh:"请再说一次。",            exPinyin:"Qǐng zài shuō yí cì.",           exEn:"Please say it again.", s2:{zh:"这个字怎么写？",py:"Zhège zì zěnme xiě?",ar:"كيف تكتب هذا الحرف؟"}, s3:{zh:"这个字我不认识。",py:"Zhège zì wǒ bú rènshi.",ar:"لا أعرف هذا الحرف."}},

  {id:277, zh:"在",     pinyin:"zài",         pos:"verb",     meaning:"في / يوجد في",                    exZh:"我在家。",                exPinyin:"Wǒ zài jiā.",                    exEn:"I am at home.", s2:{zh:"上课了，请大家坐好。",py:"Shàngkè le, qǐng dàjiā zuò hǎo.",ar:"بدأ الدرس، يرجى الجلوس بشكل صحيح."}, s3:{zh:"请坐在这里。",py:"Qǐng zuò zài zhèlǐ.",ar:"اجلس هنا من فضلك."}},

  {id:278, zh:"早",     pinyin:"zǎo",         pos:"adjective",meaning:"مبكر",                            exZh:"今天很早。",              exPinyin:"Jīntiān hěn zǎo.",               exEn:"It's early today.", s2:{zh:"我今天在家做作业。",py:"Wǒ jīntiān zài jiā zuò zuòyè.",ar:"سأؤدي واجبي في البيت اليوم."}, s3:{zh:"你会做这道菜吗？",py:"Nǐ huì zuò zhè dào cài ma?",ar:"هل تستطيع طبخ هذا الطبق؟"}},

  {id:279, zh:"早饭",   pinyin:"zǎofàn",      pos:"noun",     meaning:"فطور",                            exZh:"我吃早饭。",              exPinyin:"Wǒ chī zǎofàn.",                 exEn:"I eat breakfast.", s2:{zh:"妈妈每天做饭，很辛苦。",py:"Māma měitiān zuò fàn, hěn xīnkǔ.",ar:"أمي تطبخ كل يوم، إنها تعبانة كثيراً."}, s3:{zh:"今天你来做饭吧！",py:"Jīntiān nǐ lái zuò fàn ba!",ar:"اليوم دورك لتطبخ!"}},

  {id:280, zh:"早上",   pinyin:"zǎoshang",    pos:"noun",     meaning:"الصباح الباكر",                   exZh:"早上我上课。",            exPinyin:"Zǎoshang wǒ shàngkè.",           exEn:"I have class in the morning.", s2:{zh:"昨天下雨，今天很冷。",py:"Zuótiān xià yǔ, jīntiān hěn lěng.",ar:"أمطرت البارحة واليوم بارد."}, s3:{zh:"昨天你去哪儿了？",py:"Zuótiān nǐ qù nǎr le?",ar:"أين ذهبت بالأمس؟"}},

  {id:281, zh:"怎么",   pinyin:"zěnme",       pos:"pronoun",  meaning:"كيف؟",                            exZh:"你怎么来？",              exPinyin:"Nǐ zěnme lái?",                  exEn:"How did you come?", s2:{zh:"泰国的食物很好吃，你去过吗？",py:"Tàiguó de shíwù hěn hǎochī, nǐ qùguò ma?",ar:"الطعام التايلاندي لذيذ، هل زرت تايلاند؟"}, s3:{zh:"他从泰国来中国学汉语。",py:"Tā cóng Tàiguó lái Zhōngguó xué Hànyǔ.",ar:"جاء من تايلاند إلى الصين لدراسة الصينية."}},

  {id:282, zh:"怎么样", pinyin:"zěnmeyàng",   pos:"pronoun",  meaning:"كيف الحال؟ / ما رأيك؟",           exZh:"这个菜怎么样？",           exPinyin:"Zhège cài zěnmeyàng?",           exEn:"How is this dish?", s2:{zh:"他去法国旅游了。",py:"Tā qù Fǎguó lǚyóu le.",ar:"ذهب للسياحة في فرنسا."}, s3:{zh:"法语和中文都很难。",py:"Fǎyǔ hé Zhōngwén dōu hěn nán.",ar:"الفرنسية والصينية كلتاهما صعبتان."}},

  {id:283, zh:"找",     pinyin:"zhǎo",        pos:"verb",     meaning:"يبحث عن",                         exZh:"我找老师。",              exPinyin:"Wǒ zhǎo lǎoshī.",                exEn:"I'm looking for the teacher.", s2:{zh:"我找到我的书了！",py:"Wǒ zhǎodào wǒ de shū le!",ar:"وجدت كتابي!"}, s3:{zh:"我在找一家餐厅。",py:"Wǒ zài zhǎo yī jiā cāntīng.",ar:"أبحث عن مطعم."}},

  {id:284, zh:"这边",   pinyin:"zhèbiān",     pos:"pronoun",  meaning:"هنا / هذه الجهة",                 exZh:"我在这边。",              exPinyin:"Wǒ zài zhèbiān.",                exEn:"I'm here.", s2:{zh:"你在这边，我在那边。",py:"Nǐ zài zhèbiān, wǒ zài nàbiān.",ar:"أنت في هذه الجهة وأنا في تلك."}, s3:{zh:"书店在这边，快走！",py:"Shūdiàn zài zhèbiān, kuài zǒu!",ar:"المكتبة في هذه الجهة، أسرع!"}},

  {id:285, zh:"这个",   pinyin:"zhège",       pos:"pronoun",  meaning:"هذا الشيء",                       exZh:"我买这个。",              exPinyin:"Wǒ mǎi zhège.",                  exEn:"I buy this one.", s2:{zh:"这个苹果多少钱？",py:"Zhège píngguǒ duōshao qián?",ar:"بكم هذه التفاحة؟"}, s3:{zh:"这个菜真好吃！",py:"Zhège cài zhēn hǎochī!",ar:"هذا الطبق لذيذ فعلاً!"}},

  {id:286, zh:"这里",   pinyin:"zhèlǐ",       pos:"pronoun",  meaning:"هنا",                             exZh:"我住在这里。",            exPinyin:"Wǒ zhù zài zhèlǐ.",              exEn:"I live here.", s2:{zh:"我喜欢住在这里。",py:"Wǒ xǐhuan zhù zài zhèlǐ.",ar:"أحب السكن هنا."}, s3:{zh:"这里有没有超市？",py:"Zhèlǐ yǒu méiyǒu chāoshì?",ar:"هل يوجد سوبرماركت هنا؟"}},

  {id:287, zh:"真",     pinyin:"zhēn",        pos:"adverb",   meaning:"حقاً / فعلاً",                    exZh:"真好。",                  exPinyin:"Zhēn hǎo.",                      exEn:"Really good.", s2:{zh:"这首歌真好听！",py:"Zhè shǒu gē zhēn hǎotīng!",ar:"هذه الأغنية جميلة فعلاً!"}, s3:{zh:"你真的很好！",py:"Nǐ zhēn de hěn hǎo!",ar:"أنت جيد حقاً!"}},

  {id:288, zh:"正在",   pinyin:"zhèngzài",    pos:"adverb",   meaning:"الآن يقوم بـ...",                 exZh:"我正在学习。",            exPinyin:"Wǒ zhèngzài xuéxí.",             exEn:"I am studying.", s2:{zh:"妈妈正在做饭。",py:"Māma zhèngzài zuò fàn.",ar:"أمي تطبخ الآن."}, s3:{zh:"他正在打电话。",py:"Tā zhèngzài dǎ diànhuà.",ar:"هو يتحدث على الهاتف الآن."}},

  {id:289, zh:"这儿",   pinyin:"zhèr",        pos:"pronoun",  meaning:"هنا",                             exZh:"我在这儿。",              exPinyin:"Wǒ zài zhèr.",                   exEn:"I'm here.", s2:{zh:"我在这儿，你在哪儿？",py:"Wǒ zài zhèr, nǐ zài nǎr?",ar:"أنا هنا، أين أنت؟"}, s3:{zh:"等一下，我就在这儿。",py:"Děng yīxià, wǒ jiù zài zhèr.",ar:"انتظر لحظة، أنا هنا."}},

  {id:290, zh:"这些",   pinyin:"zhèxiē",      pos:"pronoun",  meaning:"هؤلاء / هذه (الأشياء)",           exZh:"我喜欢这些书。",           exPinyin:"Wǒ xǐhuan zhèxiē shū.",          exEn:"I like these books.", s2:{zh:"这些书都是中文书。",py:"Zhèxiē shū dōu shì Zhōngwén shū.",ar:"كل هذه الكتب صينية."}, s3:{zh:"你喜欢这些还是那些？",py:"Nǐ xǐhuan zhèxiē háishi nàxiē?",ar:"هل تحب هذه أم تلك؟"}},

  {id:291, zh:"只",     pinyin:"zhī",         pos:"particle", meaning:"(عداد للحيوانات)",               exZh:"一只猫。",                exPinyin:"Yì zhī māo.",                    exEn:"One cat.", s2:{zh:"这里只有一本书。",py:"Zhèlǐ zhǐ yǒu yī běn shū.",ar:"هنا كتاب واحد فقط."}, s3:{zh:"我只有五分钟。",py:"Wǒ zhǐ yǒu wǔ fēnzhōng.",ar:"لدي خمس دقائق فقط."}},

  {id:292, zh:"知道",   pinyin:"zhīdào",      pos:"verb",     meaning:"يعرف / يعلم",                     exZh:"我知道了。",              exPinyin:"Wǒ zhīdào le.",                  exEn:"I know.", s2:{zh:"我不知道他叫什么名字。",py:"Wǒ bù zhīdào tā jiào shénme míngzi.",ar:"لا أعرف ما اسمه."}, s3:{zh:"你知道今天是几号吗？",py:"Nǐ zhīdào jīntiān shì jǐ hào ma?",ar:"هل تعرف ما هو تاريخ اليوم؟"}},

  {id:293, zh:"中午",   pinyin:"zhōngwǔ",     pos:"noun",     meaning:"الظهيرة",                         exZh:"中午见。",                exPinyin:"Zhōngwǔ jiàn.",                  exEn:"See you at noon.", s2:{zh:"中午见，我们一起吃饭。",py:"Zhōngwǔ jiàn, wǒmen yīqǐ chī fàn.",ar:"نلتقي في الظهيرة ونأكل معاً."}, s3:{zh:"中午十二点下课。",py:"Zhōngwǔ shí'èr diǎn xiàkè.",ar:"ينتهي الدرس في الثانية عشرة ظهراً."}},

  {id:294, zh:"中学",   pinyin:"zhōngxué",    pos:"noun",     meaning:"مدرسة متوسطة",                    exZh:"他在中学学习。",           exPinyin:"Tā zài zhōngxué xuéxí.",         exEn:"He studies at a middle school.", s2:{zh:"我弟弟在中学读书。",py:"Wǒ dìdi zài zhōngxué dúshū.",ar:"أخي الأصغر يدرس في الثانوية."}, s3:{zh:"中学的学习比小学难。",py:"Zhōngxué de xuéxí bǐ xiǎoxué nán.",ar:"الدراسة في الثانوية أصعب من الابتدائية."}},

  {id:295, zh:"中学生", pinyin:"zhōngxuéshēng",pos:"noun",    meaning:"طالب متوسطة",                     exZh:"她是中学生。",             exPinyin:"Tā shì zhōngxuéshēng.",          exEn:"She is a middle school student.", s2:{zh:"中学生应该好好学习。",py:"Zhōngxuéshēng yīnggāi hǎohǎo xuéxí.",ar:"يجب على طلاب الثانوية الدراسة بجدية."}, s3:{zh:"她的哥哥是中学生。",py:"Tā de gēge shì zhōngxuéshēng.",ar:"أخوها الأكبر طالب ثانوي."}},

  {id:296, zh:"住",     pinyin:"zhù",         pos:"verb",     meaning:"يسكن / يعيش في",                  exZh:"我住在北京。",            exPinyin:"Wǒ zhù zài Běijīng.",            exEn:"I live in Beijing.", s2:{zh:"我在北京住了三年。",py:"Wǒ zài Běijīng zhù le sān nián.",ar:"سكنت في بكين لمدة ثلاث سنوات."}, s3:{zh:"你住在哪个城市？",py:"Nǐ zhù zài nǎge chéngshì?",ar:"في أي مدينة تسكن؟"}},

  {id:297, zh:"桌子",   pinyin:"zhuōzi",      pos:"noun",     meaning:"طاولة",                           exZh:"书在桌子上。",            exPinyin:"Shū zài zhuōzi shàng.",          exEn:"The book is on the table.", s2:{zh:"书在桌子上面。",py:"Shū zài zhuōzi shàngmiàn.",ar:"الكتاب فوق الطاولة."}, s3:{zh:"我们需要一张大桌子。",py:"Wǒmen xūyào yī zhāng dà zhuōzi.",ar:"نحتاج إلى طاولة كبيرة."}},

  {id:298, zh:"字",     pinyin:"zì",          pos:"noun",     meaning:"حرف / كلمة",                      exZh:"这个字很难。",            exPinyin:"Zhège zì hěn nán.",              exEn:"This character is difficult.", s2:{zh:"这个字怎么读？",py:"Zhège zì zěnme dú?",ar:"كيف تنطق هذا الحرف؟"}, s3:{zh:"我会写一百个汉字了。",py:"Wǒ huì xiě yī bǎi gè Hànzì le.",ar:"أستطيع كتابة مئة حرف صيني."}},

  {id:299, zh:"坐",     pinyin:"zuò",         pos:"verb",     meaning:"يجلس",                            exZh:"请坐。",                  exPinyin:"Qǐng zuò.",                      exEn:"Please sit.", s2:{zh:"请坐，别站着。",py:"Qǐng zuò, bié zhànzhe.",ar:"اجلس، لا تقف."}, s3:{zh:"他坐在我旁边。",py:"Tā zuò zài wǒ pángbiān.",ar:"هو جالس بجانبي."}},

  {id:300, zh:"做",     pinyin:"zuò",         pos:"verb",     meaning:"يفعل / يصنع",                     exZh:"我做作业。",              exPinyin:"Wǒ zuò zuòyè.",                  exEn:"I do homework.", s2:{zh:"你做什么工作？",py:"Nǐ zuò shénme gōngzuò?",ar:"ماذا تعمل؟"}, s3:{zh:"他每天做很多事情。",py:"Tā měitiān zuò hěn duō shìqing.",ar:"يفعل كثيراً من الأشياء كل يوم."}},

  {id:301, zh:"做饭",   pinyin:"zuò fàn",     pos:"fixed",    meaning:"يطبخ",                            exZh:"我在做饭。",              exPinyin:"Wǒ zài zuò fàn.",                exEn:"I am cooking.", s2:{zh:"妈妈在做饭，快回家！",py:"Māma zài zuò fàn, kuài huí jiā!",ar:"أمي تطبخ، ارجع للبيت بسرعة!"}, s3:{zh:"他会做很多中国菜。",py:"Tā huì zuò hěn duō Zhōngguó cài.",ar:"يعرف طبخ كثير من الأطباق الصينية."}},

  {id:302, zh:"昨天",   pinyin:"zuótiān",     pos:"noun",     meaning:"أمس",                             exZh:"昨天我上班。",            exPinyin:"Zuótiān wǒ shàngbān.",           exEn:"I worked yesterday.", s2:{zh:"昨天我去了超市买菜。",py:"Zuótiān wǒ qù le chāoshì mǎi cài.",ar:"ذهبت أمس إلى السوبرماركت لشراء الخضار."}, s3:{zh:"昨天真的很冷！",py:"Zuótiān zhēn de hěn lěng!",ar:"كان البارحة بارداً فعلاً!"}},

  
  {id:303, zh:"泰国",   pinyin:"Tàiguó",      pos:"noun",     meaning:"تايلاند",                         exZh:"他是泰国人。",            exPinyin:"Tā shì Tàiguó rén.",             exEn:"He is Thai.", s2:{zh:"我想去泰国旅游。",py:"Wǒ xiǎng qù Tàiguó lǚyóu.",ar:"أريد السياحة في تايلاند."}, s3:{zh:"泰国的天气很热。",py:"Tàiguó de tiānqì hěn rè.",ar:"طقس تايلاند حار جداً."}},

  {id:304, zh:"法国",   pinyin:"Fǎguó",       pos:"noun",     meaning:"فرنسا",                           exZh:"她去法国。",              exPinyin:"Tā qù Fǎguó.",                   exEn:"She goes to France.", s2:{zh:"法国的葡萄酒很有名。",py:"Fǎguó de pútaojiǔ hěn yǒumíng.",ar:"نبيذ فرنسا مشهور جداً."}, s3:{zh:"我想去法国学法语。",py:"Wǒ xiǎng qù Fǎguó xué Fǎyǔ.",ar:"أريد الذهاب إلى فرنسا لتعلم الفرنسية."}}

]